bool pesoOk = double.TryParse(textoPeso, out double peso)
    && peso >= 2 && peso <= 400;
bool alturaOk = double.TryParse(textoAltura, out double altura)
    && altura >= 0.5 && altura <= 2.5;

if (string.IsNullOrWhiteSpace(nome))
{
    Console.WriteLine("Informe um nome para o relatório.");
}
else if (!pesoOk)
{
    Console.WriteLine($"Peso inválido: '{textoPeso}'. Ex.: 68,5");
}
else if (!alturaOk)
{
    Console.WriteLine($"Altura inválida: '{textoAltura}'. Ex.: 1,64");
}
else
{
    double imc = peso / (altura * altura);
    string faixa = imc switch
    {
        < 18.5 => "abaixo do peso",
        < 25 => "peso normal",
        < 30 => "sobrepeso",
        < 35 => "obesidade grau I",
        < 40 => "obesidade grau II",
        _ => "obesidade grau III"
    };
    string conselho = imc switch
    {
        < 18.5 => "Um nutricionista ajuda a ganhar peso com saúde.",
        < 25 => "Continue assim: comida de verdade e movimento.",
        < 30 => "Caminhar e cortar ultraprocessados ajuda muito.",
        _ => "Vale marcar uma consulta para montar um plano."
    };
    double pesoMin = 18.5 * altura * altura;
    double pesoMax = 24.9 * altura * altura;
    Console.WriteLine($"{nome}, seu IMC é {imc:F1}: {faixa}.");
    string faixaPeso = $"{pesoMin:F1} a {pesoMax:F1} kg";
    Console.WriteLine($"Peso normal para {altura} m: {faixaPeso}");
    Console.WriteLine(conselho);
    Console.WriteLine("Lembrete: IMC é triagem, não diagnóstico.");
}

