TipoDia tipo = textoDia switch
{
    "qua" => TipoDia.Promocional,
    "sab" or "dom" => TipoDia.FimDeSemana,
    "seg" or "ter" or "qui" or "sex" => TipoDia.Util,
    _ => TipoDia.Invalido
};

if (tipo == TipoDia.Invalido || !horaOk || !idadeOk)
{
    Console.WriteLine("Dados inválidos: revise dia, sessão e idade.");
