var rng = new Random(42);
const int Chances = 7;
int rodada = 0;
int pontosTotais = 0;
string resposta;
Console.WriteLine("=== ADIVINHE O NÚMERO (1 a 100) ===");
do
{
    rodada++;
    int secreto = rng.Next(1, 101);
    int vezes = 0;
    bool acertou = false;
    Console.WriteLine($"-- Rodada {rodada}: {Chances} chances --");
    while (!acertou && vezes < Chances)
    {
        string? texto = Console.ReadLine();
        if (texto == null)
        {
            break;
        }
        if (!int.TryParse(texto, out int chute)
            || chute < 1 || chute > 100)
        {
            Console.WriteLine($"'{texto}' não vale: use de 1 a 100");
            continue;
        }
        vezes++;
        acertou = chute == secreto;
        if (acertou)
        {
            int ganhos = 100 - (vezes - 1) * 10;
            pontosTotais += ganhos;
            Console.WriteLine($"{chute}: ACERTOU! +{ganhos} pts");
        }
        else
        {
            string dica = chute < secreto ? "é maior" : "é menor";
            Console.WriteLine($"{chute}: {dica} ({vezes}/{Chances})");
        }
    }
    if (!acertou)
    {
        Console.WriteLine($"Não foi dessa vez. Era {secreto}.");
    }
    Console.WriteLine("Jogar de novo? (s/n)");
    resposta = (Console.ReadLine() ?? "n").Trim().ToLower();
} while (resposta == "s");
Console.WriteLine($"Fim! {rodada} rodadas, {pontosTotais} pontos.");

