char[,] tab =
{
    { ' ', ' ', ' ' },
    { ' ', ' ', ' ' },
    { ' ', ' ', ' ' },
};
char vez = 'X';
char vencedor = ' ';
int jogadas = 0;

while (vencedor == ' ' && jogadas < 9)
{
    string linha = Console.ReadLine() ?? "fim";
    if (linha == "fim")
    {
        break;
    }
    string[] partes = linha.Split(' ',
        StringSplitOptions.RemoveEmptyEntries);
    int lin = 0, col = 0;
    bool numeros = partes.Length == 2
        && int.TryParse(partes[0], out lin)
        && int.TryParse(partes[1], out col);
    if (!numeros || lin < 1 || lin > 3 || col < 1 || col > 3)
    {
        Console.WriteLine($"{vez}: jogada inválida ({linha})");
        continue;
    }
    if (tab[lin - 1, col - 1] != ' ')
    {
        Console.WriteLine($"{vez}: a casa {lin} {col} está ocupada");
        continue;
    }
    tab[lin - 1, col - 1] = vez;
    jogadas++;
    Console.WriteLine($"{vez} jogou em {lin} {col}");

    string trio = new string(vez, 3);
    string diag1 = $"{tab[0, 0]}{tab[1, 1]}{tab[2, 2]}";
    string diag2 = $"{tab[0, 2]}{tab[1, 1]}{tab[2, 0]}";
    bool venceu = diag1 == trio || diag2 == trio;
    for (int i = 0; i < 3; i++)
    {
        string naLinha = $"{tab[i, 0]}{tab[i, 1]}{tab[i, 2]}";
        string naColuna = $"{tab[0, i]}{tab[1, i]}{tab[2, i]}";
        venceu = venceu || naLinha == trio || naColuna == trio;
