    {
        return TentarDividir(a, b, out double quociente)
            ? $"{a} / {b} = {quociente:F2}"
            : $"{a} / {b} = erro: divisão por zero";
    }
    return opcao switch
    {
        1 => $"{a} + {b} = {Somar(a, b)}",
        2 => $"{a} - {b} = {Subtrair(a, b)}",
        3 => $"{a} x {b} = {Multiplicar(a, b)}",
        _ => $"opção {opcao} não existe"
    };
}

static double Somar(double a, double b) => a + b;
static double Subtrair(double a, double b) => a - b;
static double Multiplicar(double a, double b) => a * b;

static bool TentarDividir(double a, double b, out double resultado)
{
    if (b == 0)
    {
        resultado = 0;
        return false;
    }
    resultado = a / b;
    return true;
}

int vidaHeroi = 100;
int xpHeroi = 0;
Console.WriteLine("A aventura começa!");
MostrarStatus(vidaHeroi, xpHeroi);

Console.WriteLine("Um goblin ataca!");
LevarDano(ref vidaHeroi, Dano(ataque: 18, defesa: 5));
xpHeroi += 120;
MostrarStatus(vidaHeroi, xpHeroi);

Console.WriteLine("O troll acerta um golpe crítico!");
LevarDano(ref vidaHeroi, Dano(ataque: 30, defesa: 5, critico: true));
xpHeroi += 300;
MostrarStatus(vidaHeroi, xpHeroi);

Console.WriteLine("Você bebe uma poção grande.");
Curar(ref vidaHeroi, 80);
MostrarStatus(vidaHeroi, xpHeroi);

static int Dano(int ataque, int defesa, bool critico = false)
{
    int dano = Math.Max(1, ataque - defesa);
    return critico ? dano * 2 : dano;
}

static void LevarDano(ref int vida, int dano)
{
    vida = Math.Max(0, vida - dano);
    Console.WriteLine($"  -{dano} de vida");
}

static void Curar(ref int vida, int quanto, int maximo = 100)
{
    int antes = vida;
    vida = Math.Min(maximo, vida + quanto);
    Console.WriteLine($"  +{vida - antes} de vida (teto {maximo})");
}

static (int Nivel, int Falta) NivelPorXp(int xp)
{
    const int XpPorNivel = 200;
    return (1 + xp / XpPorNivel, XpPorNivel - xp % XpPorNivel);
}

static void MostrarStatus(int vida, int xp)
{
    var (nivel, falta) = NivelPorXp(xp);
    string barra = new string('#', vida / 10).PadRight(10, '.');
    Console.WriteLine($"  [{barra}] {vida} HP");
    Console.WriteLine($"  nível {nivel}, faltam {falta} xp");
}

Console.WriteLine("===== CÂMBIO DA PRAÇA =====");
Console.WriteLine(Converter(100m, "USD"));
Console.WriteLine(Converter(100m, "EUR", taxaServico: 0m));
Console.WriteLine(Converter(250m, moeda: "ARS", casas: 0));
Console.WriteLine(Converter(moeda: "GBP", reais: 1000m,
    taxaServico: 0.015m));
Console.WriteLine(Converter(80m, "XYZ"));
Console.WriteLine();
MostrarTabela(500m, "USD", "EUR", "GBP", "JPY");

static decimal Cotacao(string moeda) => moeda switch
{
    "USD" => 5.40m,
    "EUR" => 5.85m,
    "GBP" => 6.90m,
    "ARS" => 0.0055m,
    "JPY" => 0.037m,
    _ => 0m
};

static string Converter(decimal reais, string moeda,
    decimal taxaServico = 0.03m, int casas = 2)
{
    decimal cotacao = Cotacao(moeda);
    if (cotacao == 0m)
    {
        return $"{moeda}: moeda não atendida";
    }
    decimal liquido = reais * (1 - taxaServico);
    decimal convertido = Math.Round(liquido / cotacao, casas);
    string valor = convertido.ToString($"N{casas}");
    return $"{reais:C} -> {valor} {moeda} (taxa {taxaServico:P1})";
}

static void MostrarTabela(decimal reais, params string[] moedas)
{
    Console.WriteLine($"Quanto rendem {reais:C}:");
    foreach (string moeda in moedas)
    {
        Console.WriteLine($"  {Converter(reais, moeda, casas: 1)}");
    }
}

