    "2147483647 + 1", "9 -", "40 % 6"
];
int certas = 0;
int processadas = 0;

static int Calcular(string conta)
{
    string[] partes = conta.Split(' ');
    if (partes.Length != 3)
    {
        throw new ArgumentException(
            "Use o formato: número, operador e número.");
    }
    int a = int.Parse(partes[0]);
    int b = int.Parse(partes[2]);
    return partes[1] switch
    {
        "+" => checked(a + b),
        "-" => checked(a - b),
        "x" => checked(a * b),
        "/" => a / b,
        _ => throw new ArgumentException(
            $"O operador '{partes[1]}' não existe aqui.")
    };
}

foreach (string conta in contas)
{
    try
    {
        Console.WriteLine($"{conta} = {Calcular(conta)}");
        certas++;
    }
    catch (FormatException)
    {
        Console.WriteLine($"{conta} -> use só algarismos.");
    }
    catch (DivideByZeroException)
    {
        Console.WriteLine($"{conta} -> não existe divisão por zero.");
    }
    catch (OverflowException)
    {
        Console.WriteLine($"{conta} -> resultado grande demais.");
    }
    catch (ArgumentException ex)
    {
        Console.WriteLine($"{conta} -> {ex.Message}");
    }
    finally
    {
        processadas++;
    }
}
Console.WriteLine($"Certas: {certas} de {processadas}");

decimal saldo = 250m;
List<string> extrato = [];
(string Tipo, string Valor)[] pedidos =
[
    ("saque", "80"), ("saque", "-5"), ("pix", "5"), ("saque", "900"),
    ("deposito", "cem"), ("deposito", "45,50"), ("saque", "115,50")
];

decimal Sacar(decimal valor)
{
    ArgumentOutOfRangeException.ThrowIfNegativeOrZero(valor);
    if (valor > saldo)
    {
        throw new InvalidOperationException(
            $"Saldo insuficiente: você tem {saldo:C}.");
    }
    saldo -= valor;
    extrato.Add($"Saque     -{valor,10:C}");
    return saldo;
}

decimal Depositar(decimal valor)
{
    ArgumentOutOfRangeException.ThrowIfNegativeOrZero(valor);
    saldo += valor;
    extrato.Add($"Depósito  +{valor,10:C}");
    return saldo;
}

decimal Operar(string tipo, decimal valor) => tipo switch
{
    "saque" => Sacar(valor),
    "deposito" => Depositar(valor),
    _ => throw new InvalidOperationException($"'{tipo}' sem suporte.")
};

foreach (var (tipo, texto) in pedidos)
{
    Console.Write($"{tipo} {texto}: ");
    if (!decimal.TryParse(texto, out decimal valor))
    {
        Console.WriteLine("valor não entendido, use só números.");
        continue;
    }
    try
    {
        Console.WriteLine($"ok, saldo {Operar(tipo, valor):C}");
    }
    catch (ArgumentOutOfRangeException)
    {
        Console.WriteLine("o valor precisa ser maior que zero.");
    }
    catch (InvalidOperationException ex)
    {
        Console.WriteLine(ex.Message);
    }
}
Console.WriteLine("----- extrato -----");
Console.WriteLine(string.Join("\n", extrato));
Console.WriteLine($"Saldo final: {saldo:C}");

string[] fases = ["Praia do Forte", "Caverna Azul", "Castelo Final"];
string[] saves =
[
    "fase=2", "fase=0", "fase=dois", "vida=3", "fase=9"
];

string CarregarFase(int numero)
{
    ArgumentOutOfRangeException.ThrowIfLessThan(numero, 1);
    ArgumentOutOfRangeException.ThrowIfGreaterThan(
        numero, fases.Length);
    return fases[numero - 1];
}

static int LerSave(string save)
{
    string[] partes = save.Split('=');
    if (partes.Length != 2 || partes[0] != "fase")
    {
        throw new InvalidOperationException(
            $"Save '{save}' não tem o campo fase.");
    }
    try
    {
        return int.Parse(partes[1]);
    }
    catch (FormatException ex)
    {
        throw new InvalidOperationException(
            $"Save '{save}' corrompido.", ex);
    }
}

int carregadas = 0;
foreach (string save in saves)
{
    try
    {
        string nome = CarregarFase(LerSave(save));
        Console.WriteLine($"[{save}] Carregando: {nome}");
        carregadas++;
    }
    catch (ArgumentOutOfRangeException ex)
        when (ex.ParamName == "numero")
    {
        Console.WriteLine($"[{save}] Fase não existe: menu.");
    }
    catch (InvalidOperationException ex)
    {
        Console.WriteLine($"[{save}] {ex.Message}");
        if (ex.InnerException != null)
        {
            string causa = ex.InnerException.GetType().Name;
            Console.WriteLine($"    causa: {causa}");
        }
    }
}
Console.WriteLine($"Carregados: {carregadas} de {saves.Length}");

