class ContaCorrente(string titular, decimal limite)
{
    private const int PrimeiroNumero = 1001;
    private static int s_proximo = PrimeiroNumero;
    private readonly List<string> _extrato = [];

    public int Numero { get; } = s_proximo++;
    public string Titular { get; } = titular;
    public decimal Limite { get; } = limite;
    public decimal Saldo { get; private set; }
    public static int Abertas => s_proximo - PrimeiroNumero;

    public void Depositar(decimal valor, string motivo = "depósito")
    {
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(valor);
        Saldo += valor;
        _extrato.Add($"+ {valor,11:C}  {motivo}");
    }

    public bool Sacar(decimal valor, string motivo = "saque")
    {
        if (valor <= 0 || valor > Saldo + Limite)
        {
            _extrato.Add($"  {valor,11:C}  {motivo} NEGADO");
            return false;
        }
        Saldo -= valor;
        _extrato.Add($"- {valor,11:C}  {motivo}");
        return true;
    }

    public void Transferir(ContaCorrente destino, decimal valor)
    {
        if (Sacar(valor, $"pix para {destino.Titular}"))
            destino.Depositar(valor, $"pix de {Titular}");
    }

    public void ImprimirExtrato()
    {
        Console.WriteLine($"== Conta {Numero} - {Titular} ==");
        foreach (var linha in _extrato) Console.WriteLine(linha);
        Console.WriteLine($"Saldo: {Saldo:C} (limite {Limite:C})");
    }
}

