class Personagem(string nome, string classe)
{
    public const int XpPorNivel = 100;
    public int Nivel { get; private set; } = 1;
    public int Xp { get; private set; }
    public int Forca { get; private set; } = 5;
    public int Agilidade { get; private set; } = 8;
    public int VidaMaxima => 50 + Nivel * 10;
    public bool Desmaiado => Vida == 0;
    public int Vida
    {
        get;
        private set => field = Math.Clamp(value, 0, VidaMaxima);
    } = 60;

    public void GanharXp(int pontos)
    {
        Xp += pontos;
        while (Xp >= XpPorNivel)
        {
            Xp -= XpPorNivel;
            SubirDeNivel();
        }
    }

    public void LevarDano(int dano) => Vida -= dano;
    public void Curar(int pontos) => Vida += pontos;

    public string Atributos() =>
        $"FOR {Forca} | AGI {Agilidade} | Nv {Nivel} {classe}";

    public override string ToString()
    {
        string estado = Desmaiado ? " [desmaiada]" : "";
        return $"{nome}: HP {Vida}/{VidaMaxima}, XP {Xp}{estado}";
    }

    private void SubirDeNivel()
    {
        Nivel++;
        Forca += 2;
        Agilidade += 3;
        Vida = VidaMaxima;
        Console.WriteLine($"*** {nome} chegou ao nível {Nivel}! ***");
    }
}

