estoque.Cadastrar(new Produto("Café 500 g", 18.90m, 20, minimo: 6));
estoque.Vender("Arroz 5 kg", 9);
estoque.Vender("Café 500 g", 25);
estoque.Vender("Farinha", 1);
estoque.Relatorio("Fim da manhã");
estoque.Buscar("Feijão 1 kg")?.Repor(10);
estoque.Relatorio("Depois da reposição");

class Produto(string nome, decimal preco, int quantidade, int minimo)
{
    public string Nome { get; } = nome;
    public decimal Preco { get; } = preco;
    public int Quantidade { get; private set; } = quantidade;
    public bool EstoqueBaixo => Quantidade <= minimo;
    public bool Retirar(int qtd)
    {
        if (qtd <= 0 || qtd > Quantidade) return false;
        Quantidade -= qtd;
        return true;
    }

    public void Repor(int qtd) => Quantidade += qtd;
}

class Estoque
{
    private readonly List<Produto> _produtos = [];
    public void Cadastrar(Produto p) => _produtos.Add(p);

    public Produto? Buscar(string nome)
    {
        foreach (var p in _produtos)
        {
            if (p.Nome == nome) return p;
        }
        return null;
    }

    public void Vender(string nome, int qtd)
    {
        bool ok = Buscar(nome)?.Retirar(qtd) ?? false;
        Console.WriteLine($"{qtd}x {nome}: {(ok ? "ok" : "negada")}");
    }

    public void Relatorio(string titulo)
    {
        Console.WriteLine($"== {titulo} ==");
        decimal total = 0;
        foreach (var p in _produtos)
        {
            string aviso = p.EstoqueBaixo ? "  <- REPOR" : "";
            Console.WriteLine($"{p.Nome,-12}{p.Quantidade,4}{aviso}");
            total += p.Preco * p.Quantidade;
        }
        Console.WriteLine($"Valor parado no estoque: {total:C}");
    }
}

