interface IAtacavel
{
    string Nome { get; }
    void ReceberDano(int dano);
}

abstract class Heroi(string nome, int vida) : IAtacavel
{
    public string Nome { get; } = nome;
    public int Vida { get; private set; } = vida;
    public void ReceberDano(int dano) =>
        Vida = Math.Max(0, Vida - Defender(dano));
    protected virtual int Defender(int dano) => dano;
    public abstract void Atacar(IAtacavel alvo);
    protected void Golpe(IAtacavel alvo, string acao, int dano)
    {
        Console.WriteLine($"{Nome} {acao} ({dano})");
        alvo.ReceberDano(dano);
    }
}

class Guerreiro(string nome) : Heroi(nome, 120)
{
    public override void Atacar(IAtacavel alvo) =>
        Golpe(alvo, "golpeia com o machado", 22);
    protected override int Defender(int dano) => dano / 2;
}

