{
    int _cargas = 2;
    public override void Atacar(IAtacavel alvo) =>
        Golpe(alvo, "lança feitiço", _cargas-- > 0 ? 40 : 8);
}

class Arqueiro(string nome) : Heroi(nome, 85)
{
    int _tiros;
    public override void Atacar(IAtacavel alvo) =>
        Golpe(alvo, "dispara", ++_tiros % 2 == 0 ? 30 : 15);
}

sealed class Monstro(string nome, int vida, int forca) : IAtacavel
{
    public string Nome { get; } = nome;
    public int Vida { get; private set; } = vida;
    public void ReceberDano(int dano) =>
        Vida = Math.Max(0, Vida - dano);
    public void Atacar(IAtacavel alvo) => alvo.ReceberDano(forca);
}

