readonly record struct Vetor2D(double X, double Y)
{
    public static Vetor2D Zero => new(0, 0);

    public double Comprimento => Math.Sqrt(X * X + Y * Y);

    public Vetor2D Normalizado =>
        Comprimento == 0 ? Zero : this / Comprimento;

    public static Vetor2D operator +(Vetor2D a, Vetor2D b) =>
        new(a.X + b.X, a.Y + b.Y);

    public static Vetor2D operator -(Vetor2D a, Vetor2D b) =>
        new(a.X - b.X, a.Y - b.Y);

    public static Vetor2D operator *(Vetor2D v, double k) =>
        new(v.X * k, v.Y * k);

    public static Vetor2D operator /(Vetor2D v, double k) =>
        new(v.X / k, v.Y / k);

    public override string ToString() => $"({X:F1}; {Y:F1})";
}

