    ("Mordida de jararaca", Condicao.Envenenado, false),
    ("Bola de fogo", Condicao.Queimando, false),
    ("Rajada de gelo", Condicao.Congelado, false),
    ("Poção de antídoto", Condicao.Envenenado, true),
    ("Golpe de clava", Condicao.Atordoado, false),
    ("Fogueira", Condicao.Queimando, false)
];

foreach (var (evento, efeito, cura) in roteiro)
{
    if (cura)
    {
        iracema.Curar(efeito);
    }
    else
    {
        iracema.Aplicar(efeito);
    }
    Console.WriteLine($"{evento,-20} {iracema.PassarTurno()}");
}

[Flags]
enum Condicao
{
    Nenhuma = 0,
    Envenenado = 1 << 0,
    Congelado = 1 << 1,
    Queimando = 1 << 2,
    Atordoado = 1 << 3,
    Incapacitado = Congelado | Atordoado
}

class Heroi(string nome, int vidaInicial)
{
    public int Vida { get; private set; } = vidaInicial;
    public Condicao Estado { get; private set; }
    public void Aplicar(Condicao nova)
    {
        Condicao anula = nova switch
        {
            Condicao.Queimando => Condicao.Congelado,
            Condicao.Congelado => Condicao.Queimando,
            _ => Condicao.Nenhuma
        };
        Estado = (Estado & ~anula) | nova;
    }
    public void Curar(Condicao efeito) => Estado &= ~efeito;
    public string PassarTurno()
    {
        int dano = 0;
        if (Estado.HasFlag(Condicao.Envenenado))
        {
            dano += 5;
        }
        if (Estado.HasFlag(Condicao.Queimando))
        {
            dano += 8;
        }
        Vida = Math.Max(0, Vida - dano);
        bool parado = (Estado & Condicao.Incapacitado) != 0;
        string acao = parado ? "perde a vez" : "ataca";
        string texto = $"{nome} {acao,-11} | vida {Vida,3} | {Estado}";
        Estado &= ~Condicao.Atordoado;
        return texto;
    }
}

