bool Balanceado(string texto)
{
    Stack<char> esperados = new();
    foreach (char c in texto)
    {
        if (c == '(') esperados.Push(')');
        else if (c == '[') esperados.Push(']');
        else if (c == ')' || c == ']')
        {
            if (!esperados.TryPop(out char fecha) || fecha != c)
            {
                return false; // fechou o que não estava aberto
            }
        }
    }
    return esperados.Count == 0;  // sobrou algo aberto?
}
Console.WriteLine(Balanceado("(2 + [3 * 4])")); // True
Console.WriteLine(Balanceado("(2 + [3 * 4)]")); // False

