class PlacaIgual : IEqualityComparer<string>
{
    static string Limpar(string? s) =>
        (s ?? "").Replace("-", "").ToUpperInvariant();
    public bool Equals(string? x, string? y) =>
        Limpar(x) == Limpar(y);
    public int GetHashCode(string obj) => Limpar(obj).GetHashCode();
}

