class PorTamanho : IComparer<string>
{
    public int Compare(string? x, string? y)
    {
        int tamanho = (x ?? "").Length.CompareTo((y ?? "").Length);
        return tamanho != 0 ? tamanho : string.CompareOrdinal(x, y);
    }
}

