string texto = """
    Na feira de domingo, a banca de frutas abre cedo. A banca de
    pastel abre depois, mas a fila do pastel cresce rápido. Quem
    chega cedo leva a fruta mais doce; quem chega tarde leva o
    pastel mais quente. Domingo é dia de feira, e feira é festa!
    """;
HashSet<string> ignorar = new(StringComparer.OrdinalIgnoreCase)
{
    "a", "o", "de", "do", "e", "é", "mas", "na", "mais", "quem"
};
char[] separadores = [' ', '\n', '\r', ',', '.', ';', '!'];
string[] palavras = texto.Split(separadores,
    StringSplitOptions.RemoveEmptyEntries);

SortedDictionary<string, int> frequencia = new();
int ignoradas = 0;
foreach (string bruta in palavras)
{
    string palavra = bruta.ToLower();
    if (ignorar.Contains(palavra))
    {
        ignoradas++;
        continue;
    }
    frequencia[palavra] = frequencia.GetValueOrDefault(palavra) + 1;
}

Console.WriteLine($"Palavras no texto: {palavras.Length}");
Console.WriteLine($"Ignoradas (muito comuns): {ignoradas}");
Console.WriteLine($"Palavras diferentes: {frequencia.Count}");
Console.WriteLine("--- Repetidas, em ordem alfabética ---");
PriorityQueue<string, (int, string)> ranking = new();
foreach (var (palavra, vezes) in frequencia)
{
    if (vezes > 1)
    {
        string barra = new string('*', vezes);
        Console.WriteLine($"{palavra,-8}{barra,-4}{vezes}");
    }
    ranking.Enqueue(palavra, (-vezes, palavra));
}

Console.WriteLine("--- Pódio ---");
for (int lugar = 1; lugar <= 3; lugar++)
{
    string palavra = ranking.Dequeue();
    int vezes = frequencia[palavra];
    Console.WriteLine($"Lugar {lugar}: {palavra} ({vezes}x)");
}

