};
Queue<Paciente> portaria = new(
[
    new Paciente("Seu Antônio", 4, "dor de garganta"),
    new Paciente("Dona Rita", 2, "falta de ar"),
    new Paciente("Joãozinho", 5, "pedir atestado"),
