const int PorPilha = 20;
const int MaxSlots = 6;
Dictionary<string, int> mochila =
    new(StringComparer.OrdinalIgnoreCase);
int usados = 0;

int Slots(int qtd) => (qtd + PorPilha - 1) / PorPilha;

void Guardar(string item, int qtd)
{
    int atual = mochila.GetValueOrDefault(item);
    int livres = MaxSlots - usados + Slots(atual);
    int cabe = Math.Min(qtd, livres * PorPilha - atual);
    if (cabe > 0)
    {
        mochila[item] = atual + cabe;
        usados += Slots(atual + cabe) - Slots(atual);
    }
    string resto = cabe < qtd ? $" ({qtd - cabe} no chão)" : "";
    Console.WriteLine($"+ {cabe} {item}{resto}");
}

void Usar(string item, int qtd)
{
    if (!mochila.TryGetValue(item, out int tem) || tem < qtd)
    {
        Console.WriteLine($"x não tem {qtd} {item}");
        return;
    }
    mochila[item] = tem - qtd;
    usados -= Slots(tem) - Slots(tem - qtd);
    if (tem == qtd)
    {
        mochila.Remove(item);
    }
    Console.WriteLine($"- {qtd} {item}");
}

void Mostrar()
{
    List<string> nomes = [.. mochila.Keys];
    nomes.Sort();
    Console.WriteLine($"== Mochila {usados}/{MaxSlots} ==");
    foreach (string nome in nomes)
    {
        int qtd = mochila[nome];
        Console.WriteLine($"{nome,-15}{qtd,4}  slots: {Slots(qtd)}");
    }
}

