class ContadorRegressivo(int inicio) : IEnumerator<int>
{
    private int _atual = inicio + 1;
    public int Current => _atual;
    object IEnumerator.Current => Current;
    public bool MoveNext() => --_atual >= 1;
    public void Reset() => _atual = inicio + 1;
    public void Dispose() => Console.WriteLine("(cursor fechado)");
}

class Regressiva(int inicio) : IEnumerable<int>
{
    public IEnumerator<int> GetEnumerator() =>
        new ContadorRegressivo(inicio);

    IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
}

