static class BaralhoExtensions
{
    public static IEnumerable<T> Metade<T>(
        this IReadOnlyList<T> cartas, int qual)
    {
        int meio = cartas.Count / 2;
        return qual == 1 ? cartas.Take(meio) : cartas.Skip(meio);
    }

    public static string Topo(this IEnumerable<string> cartas) =>
        string.Join(" ", cartas.Take(8)) + " ...";

    public static IEnumerable<T> Intercalar<T>(
        this IEnumerable<T> primeira, IEnumerable<T> segunda)
    {
        using var a = primeira.GetEnumerator();
        using var b = segunda.GetEnumerator();
        while (a.MoveNext() && b.MoveNext())
        {
            yield return a.Current;
            yield return b.Current;
        }
    }
}

