static IEnumerable<Onda> Ondas(Random rng)
{
    for (int numero = 1; ; numero++)
    {
        yield return new Onda(numero, [.. Inimigos(numero, rng)]);
    }
}

static IEnumerable<Inimigo> Inimigos(int onda, Random rng)
{
    int quantidade = 3 + onda * 2;
    for (int i = 0; i < quantidade; i++)
    {
        int sorteio = rng.Next(100) + onda * 8;
        if (sorteio < 70)
            yield return new Inimigo("morcego", 8 + onda);
        else if (sorteio < 110)
            yield return new Inimigo("esqueleto", 15 + onda * 2);
        else
            yield return new Inimigo("golem", 40 + onda * 5);
    }
    if (onda % 5 == 0)
    {
        yield return new Inimigo("chefão", 100 * onda);
    }
}

record Inimigo(string Tipo, int Vida);
record Onda(int Numero, Inimigo[] Inimigos);

