enum Status
{
    Criado, Pago, Preparando, EmRota, Entregue, Cancelado
}

static class Fluxo
{
    public static Status? Proximo(Status s, Acao a) => (s, a) switch
    {
        (Criado, Pagar) => Pago,
        (Pago, Preparar) => Preparando,
        (Preparando, Despachar) => EmRota,
        (EmRota, Entregar) => Entregue,
        (Criado or Pago, Cancelar) => Cancelado,
        _ => null
    };
}

class Pedido
{
    public Status Atual { get; private set; } = Criado;
    public List<string> Historico { get; } = [];
    public void Aplicar(Acao acao)
    {
        Status? novo = Fluxo.Proximo(Atual, acao);
        string fim = novo is { } s ? $"{s}" : "recusada";
        Historico.Add($"{Atual} + {acao} = {fim}");
        Atual = novo ?? Atual;
    }
}

var pedido = new Pedido();
Acao[] passos = [Pagar, Despachar, Preparar, Despachar, Entregar];
