record Circulo(double Raio) : Forma;
record Retangulo(double Largura, double Altura) : Forma;
record Triangulo(double A, double B, double C) : Forma;

static double Heron(double a, double b, double c)
{
    double s = (a + b + c) / 2;
    return Math.Sqrt(s * (s - a) * (s - b) * (s - c));
}

static double Area(Forma f) => f switch
{
    Circulo(var r) => Math.PI * r * r,
    Retangulo(var l, var a) => l * a,
    Triangulo(var a, var b, var c) => Heron(a, b, c),
    _ => throw new ArgumentException($"Forma nova? {f}")
};

static double Perimetro(Forma f) => f switch
{
    Circulo c => 2 * Math.PI * c.Raio,
    Retangulo r => 2 * (r.Largura + r.Altura),
    Triangulo t => t.A + t.B + t.C,
    _ => throw new ArgumentException($"Forma nova? {f}")
};

foreach (var forma in formas)
{
    string nome = forma.GetType().Name;
    Console.WriteLine($"{nome}: área {Area(forma):F2}, " +
        $"perímetro {Perimetro(forma):F2}");
}

try
{
    Console.WriteLine(Area(new Hexagono(2)));
}
catch (ArgumentException ex)
{
    Console.WriteLine(ex.Message);
}
