    new("Ana", "SP", 0.8, [new("Livro", Livros, 59.90m)]),
    new("Davi", "BA", 1.5, [new("Fone", Eletronicos, 199.90m),
        new("Carregador", Eletronicos, 59.90m)]),
    new("Rosa", "AM", 12, [new("Arroz 5 kg", Mercado, 32.50m),
        new("Panela", Casa, 149.00m)]),
    new("Téo", "PR", 7, [new("Tapete", Casa, 189.00m)]),
];

foreach (var (cliente, uf, kg, itens) in pedidos)
{
    decimal produtos = itens.Sum(i => i.Preco);
    decimal imposto = itens.Sum(i => i.Preco * Imposto(i.Categoria));
    decimal frete = Frete(uf, kg, produtos);
    decimal total = produtos + imposto + frete;
    Console.WriteLine($"{cliente} ({uf}, {kg} kg)");
    Console.WriteLine($"  Produtos {produtos,12:C}");
    Console.WriteLine($"  Impostos {imposto,12:C}");
    Console.WriteLine($"  Frete    {frete,12:C}");
    Console.WriteLine($"  Total    {total,12:C}");
}

static decimal Imposto(Categoria cat) => cat switch
{
    Livros => 0m,
    Mercado => 0.07m,
    Casa => 0.12m,
    Eletronicos => 0.18m,
    _ => throw new ArgumentOutOfRangeException(nameof(cat))
};

static decimal Frete(string uf, double kg, decimal valor) =>
    (uf, kg, valor) switch
    {
        (_, _, >= 250m) => 0m,
        ("SP" or "RJ" or "MG" or "ES", <= 1, _) => 9.90m,
        ("SP" or "RJ" or "MG" or "ES", _, _) => 19.90m,
        ("AM" or "RR" or "AP" or "AC", _, _) => 59.90m,
        (_, <= 5, _) => 24.90m,
        _ => 34.90m
    };

enum Categoria { Livros, Mercado, Casa, Eletronicos }
record Item(string Nome, Categoria Categoria, decimal Preco);
record Pedido(string Cliente, string Uf, double Kg, List<Item> Itens);

List<string> lista = [];
string[] entradas =
[
    "add arroz", "add feijão preto", "add", "listar", "remover 5",
    "remover 1", "add café", "mudar 1 feijão carioca", "listar",
    "limpar tudo", "limpar", "listar", "dançar"
];

foreach (var entrada in entradas)
{
    string[] partes = entrada.Split(' ',
        StringSplitOptions.RemoveEmptyEntries);
    Console.WriteLine($"> {entrada,-24} {Executar(partes)}");
}

string Executar(string[] cmd) => cmd switch
{
    [] => "digite algo",
    ["add"] => "add o quê?",
    ["add", .. var palavras] => Adicionar(string.Join(' ', palavras)),
    ["remover", var n] when Posicao(n, out int p) => Remover(p),
    ["mudar", var n, .. { Length: > 0 } resto]
        when Posicao(n, out int p) => Mudar(p, resto),
    ["remover" or "mudar", ..] => "posição inválida",
    ["listar"] when lista.Count == 0 => "(lista vazia)",
    ["listar"] => string.Join(" | ",
        lista.Select((item, i) => $"{i + 1}. {item}")),
    ["limpar"] => Limpar(),
    ["limpar", ..] => "use só: limpar",
    [var outro, ..] => $"não conheço '{outro}'"
};

bool Posicao(string texto, out int p) =>
    int.TryParse(texto, out p) && p >= 1 && p <= lista.Count;

string Adicionar(string item)
{
    lista.Add(item);
    return $"ok, {lista.Count} item(ns)";
}

string Remover(int p)
{
    string saiu = lista[p - 1];
    lista.RemoveAt(p - 1);
    return $"removido: {saiu}";
}

string Mudar(int p, string[] palavras)
{
    lista[p - 1] = string.Join(' ', palavras);
    return $"item {p} agora é {lista[p - 1]}";
}

string Limpar()
{
    lista.Clear();
    return "lista limpa";
}

using static EstadoPac;
using static Tecla;

Tecla[] quadros = [Direita, Direita, Pular, Nenhuma, Pular, Nenhuma,
    Nenhuma, Direita, Direita, Nenhuma, Pular, Esquerda, Nenhuma,
    Nenhuma, Nenhuma, Nenhuma, Esquerda];
var estado = Parado;
int x = 0;
int y = 0;

for (int i = 0; i < quadros.Length; i++)
{
    var tecla = quadros[i];
    var antes = estado;
    estado = Proximo(estado, tecla, y);
    y = estado switch { Pulando => y + 1, Caindo => y - 1, _ => 0 };
    x += tecla switch { Direita => 1, Esquerda => -1, _ => 0 };
    string mudou = antes == estado ? "" : $" ({antes} -> {estado})";
    Console.WriteLine($"{i + 1,2}: {tecla,-8} x={x,2} y={y}{mudou}");
}
Console.WriteLine($"Fim: Pac {estado} em x={x}, y={y}");

static EstadoPac Proximo(EstadoPac e, Tecla t, int altura) =>
    (e, t, altura) switch
    {
        (Parado or Andando, Pular, _) => Pulando,
        (Parado, Direita or Esquerda, _) => Andando,
        (Andando, Nenhuma, _) => Parado,
        (Pulando, _, >= 3) => Caindo,
        (Caindo, Direita or Esquerda, <= 1) => Andando,
        (Caindo, _, <= 1) => Parado,
        _ => e
    };

enum EstadoPac { Parado, Andando, Pulando, Caindo }
enum Tecla { Nenhuma, Direita, Esquerda, Pular }

