class RelogioFixo(DateTimeOffset instante) : TimeProvider
{
    public override DateTimeOffset GetUtcNow() => instante;
}

class Loja(TimeProvider tempo)
{
    private static readonly TimeSpan Brasilia = TimeSpan.FromHours(-3);

    public bool Aberta()
    {
        int hora = tempo.GetUtcNow().ToOffset(Brasilia).Hour;
        return hora is >= 9 and < 18;
    }
}

class RelogioManual(DateTimeOffset inicio) : TimeProvider
{
    private DateTimeOffset _agora = inicio;
    public override DateTimeOffset GetUtcNow() => _agora;
    public void Avancar(TimeSpan quanto) => _agora += quanto;
}

class BonusDiario(TimeProvider tempo)
{
    private DateTimeOffset? _ultimo;

    public bool PodeResgatar() =>
        _ultimo is null
        || tempo.GetUtcNow() - _ultimo >= TimeSpan.FromDays(1);

    public void Resgatar() => _ultimo = tempo.GetUtcNow();
}

