var feriados = new HashSet<DateOnly>
{
    new(2026, 10, 12), new(2026, 11, 2), new(2026, 11, 15),
    new(2026, 11, 20), new(2026, 12, 25),
};

bool DiaUtil(DateOnly dia) =>
    dia.DayOfWeek is not (DayOfWeek.Saturday or DayOfWeek.Sunday)
    && !feriados.Contains(dia);

DateOnly SomarDiasUteis(DateOnly inicio, int dias)
{
    var data = inicio;
    while (dias > 0)
    {
        data = data.AddDays(1);
        if (DiaUtil(data))
        {
            dias--;
        }
    }
    return data;
}

