using System.Text.RegularExpressions;

var reCpf = new Regex(@"^\d{3}\.?\d{3}\.?\d{3}-?\d{2}$");
var reCep = new Regex(@"^\d{5}-?\d{3}$");
var reCelular = new Regex(
    @"^\(?(?<ddd>[1-9]\d)\)? ?(?<num>9\d{4})-?(?<fim>\d{4})$");

bool CpfValido(string texto)
{
    string d = Regex.Replace(texto, @"\D", "");
    if (!reCpf.IsMatch(texto) || d.Distinct().Count() == 1)
    {
        return false;
    }
    for (int n = 9; n <= 10; n++)
    {
        int soma = 0;
        for (int i = 0; i < n; i++)
        {
            soma += (d[i] - '0') * (n + 1 - i);
        }
        if (soma * 10 % 11 % 10 != d[n] - '0')
        {
            return false;
        }
    }
    return true;
}

Cadastro[] cadastros =
[
    new("Joana", "529.982.247-25", "50030-230", "(81) 99876-5432"),
    new("Caio", "111.111.111-11", "01310100", "11 98765-4321"),
    new("Lúcia", "52998224726", "6906-0000", "(92) 3234-5678"),
    new("Tiago", "39053344705", "69060-000", "92912345678"),
];

int validos = 0;
foreach (var c in cadastros)
{
    var erros = new List<string>();
    if (!CpfValido(c.Cpf)) erros.Add("CPF");
    if (!reCep.IsMatch(c.Cep)) erros.Add("CEP");
    if (!reCelular.IsMatch(c.Celular)) erros.Add("celular");
    if (erros.Count > 0)
    {
        Console.WriteLine($"{c.Nome,-6} ERRO em {string.Join(", ", erros)}");
        continue;
    }
    validos++;
    string cpf = Regex.Replace(c.Cpf, @"\D", "");
    string oculto = $"***.{cpf[3..6]}.***-{cpf[9..]}";
    string fone = reCelular.Replace(c.Celular, "(${ddd}) ${num}-${fim}");
    Console.WriteLine($"{c.Nome,-6} OK   CPF {oculto}   {fone}");
}
Console.WriteLine($"{validos} de {cadastros.Length} cadastros válidos");

