List<string> SepararCsv(string linha)
{
    var campos = new List<string> { "" };
    bool entreAspas = false;
    foreach (char ch in linha)
    {
        if (ch == '"') entreAspas = !entreAspas;
        else if (ch == ';' && !entreAspas) campos.Add("");
        else campos[^1] += ch;
    }
    return campos;
}

