void Salvar(SaveJogo dados, string arquivo)
{
    if (File.Exists(arquivo))
    {
        File.Copy(arquivo, arquivo + ".bak", overwrite: true);
    }
    string temp = arquivo + ".tmp";
    File.WriteAllText(temp, JsonSerializer.Serialize(dados));
    File.Move(temp, arquivo, overwrite: true);
}

