SaveJogo? Carregar(string arquivo)
{
    if (!File.Exists(arquivo)) return null;
    string json = File.ReadAllText(arquivo);
    var dados = JsonSerializer.Deserialize<SaveJogo>(json);
    return dados switch
    {
        { Versao: VersaoAtual } => dados,
        { Versao: 1 } v1 => v1 with { Fases = v1.Fases ?? [] },
        _ => null,
    };
}

