List<string> Campos(string linha)
{
    var campos = new List<string> { "" };
    bool aspas = false;
    foreach (char ch in linha)
    {
        if (ch == '"') aspas = !aspas;
        else if (ch == ';' && !aspas) campos.Add("");
        else campos[^1] += ch;
    }
    return campos;
}

