using System.IO.Compression;
using System.Text.Json;

const int VersaoAtual = 3;
string pasta = Path.Combine("saves");
Directory.CreateDirectory(pasta);
string Caminho(int n) => Path.Combine(pasta, $"slot{n}.json.gz");

void Salvar(int slot, Progresso progresso)
{
    string destino = Caminho(slot);
    if (File.Exists(destino))
    {
        File.Copy(destino, destino + ".bak", overwrite: true);
    }
    string temp = destino + ".tmp";
    using (var gz = new GZipStream(File.Create(temp),
        CompressionLevel.SmallestSize))
    {
        JsonSerializer.Serialize(gz, progresso);
    }
    File.Move(temp, destino, overwrite: true);
}

Progresso? Carregar(int slot)
{
    if (!File.Exists(Caminho(slot))) return null;
    using var gz = new GZipStream(File.OpenRead(Caminho(slot)),
        CompressionMode.Decompress);
    var lido = JsonSerializer.Deserialize<Progresso>(gz);
    return lido?.Versao == VersaoAtual ? lido : null;
}

