class Lutador(
    string nome, int vida, int ataque, int defesa, int agilidade)
{
    public string Nome { get; } = nome;
    public int Vida { get; private set; } = vida;
    public int Ataque { get; } = ataque;
    public int Defesa { get; } = defesa;
    public int Agilidade { get; } = agilidade;
    public bool Vivo => Vida > 0;
    public void ReceberDano(int dano) =>
        Vida = Math.Max(0, Vida - dano);
}

var ordem = new[] { heroi, orc }
    .OrderByDescending(l => l.Agilidade)
    .ToArray();
Console.WriteLine($"Começa: {ordem[0].Nome}");

var dados = new Random(11);
var registro = new List<string>();
int rodada = 1;

void Atacar(Lutador atacante, Lutador alvo)
{
    bool critico = dados.Next(100) < 15; // 15% de chance
    int dano = Dano(atacante.Ataque, alvo.Defesa, critico);
    alvo.ReceberDano(dano);
    string extra = critico ? " CRÍTICO!" : "";
    registro.Add($"R{rodada}: {atacante.Nome} tira {dano}{extra}" +
        $" ({alvo.Nome} fica com {alvo.Vida})");
}

while (heroi.Vivo && orc.Vivo)
{
    foreach (var lutador in ordem)
    {
        var oponente = lutador == heroi ? orc : heroi;
