static int[] Compactar(int[] linha)
{
    var pecas = linha.Where(v => v != 0).ToList();
    while (pecas.Count < linha.Length)
    {
        pecas.Add(0);
    }
    return [.. pecas];
}

static int[] Fundir(int[] linha, ref int pontos)
{
    int[] p = Compactar(linha);
    for (int i = 0; i + 1 < p.Length; i++)
    {
        if (p[i] == 0 || p[i] != p[i + 1]) continue;
        p[i] *= 2;
        pontos += p[i];
        p[i + 1] = 0; // o zero impede a peça nova de fundir outra vez
    }
    return Compactar(p);
}

static int[][] Girar(int[][] g)
{
    int n = g.Length;
    var r = new int[n][];
    for (int c = 0; c < n; c++)
    {
        r[c] = new int[n];
        for (int l = 0; l < n; l++) r[c][l] = g[n - 1 - l][c];
    }
    return r;
}

static bool MoverEsquerda(int[][] g, ref int pontos)
{
    bool mudou = false;
    for (int l = 0; l < g.Length; l++)
    {
        int[] nova = Fundir(g[l], ref pontos);
        mudou |= !nova.SequenceEqual(g[l]);
        g[l] = nova;
    }
    return mudou;
}

static bool Mover(ref int[][] g, char dir, ref int pontos)
{
    int giros = "EBDC".IndexOf(dir); // giros até virar esquerda
    for (int i = 0; i < giros; i++) g = Girar(g);
    bool mudou = MoverEsquerda(g, ref pontos);
    for (int i = 0; i < (4 - giros) % 4; i++) g = Girar(g);
    return mudou;
}

static void NovaPeca(int[][] g, Random rng)
{
    int n = g.Length;
    var vazias = Enumerable.Range(0, n * n)
        .Where(k => g[k / n][k % n] == 0)
        .ToList();
    if (vazias.Count == 0) return;
    int casa = vazias[rng.Next(vazias.Count)];
    g[casa / n][casa % n] = rng.Next(10) == 0 ? 4 : 2;
}

