int pontos = 0, tick = 0;
foreach (char tecla in "...<......v<^>>")
{
    tick++;
    var pedido = tecla switch
    {
        '^' => (X: 0, Y: -1),
        'v' => (X: 0, Y: 1),
        '<' => (X: -1, Y: 0),
        '>' => (X: 1, Y: 0),
        _ => rumo
    };
    if (pedido == (-rumo.X, -rumo.Y))
    {
        Console.WriteLine($"Tick {tick,2}: meia-volta ignorada");
    }
    else
    {
        rumo = pedido;
    }
    var cabeca = (
        X: ((corpo[0].X + rumo.X) % Largura + Largura) % Largura,
        Y: ((corpo[0].Y + rumo.Y) % Altura + Altura) % Altura);
    if (corpo.SkipLast(1).Contains(cabeca)) // a cauda vai sair dali
    {
        Console.WriteLine($"Tick {tick,2}: mordeu o próprio corpo!");
