            from dc in new[] { -1, 0, 1 }
            where dl != 0 || dc != 0
            select (dl, dc)).ToArray();
bool Dentro(int l, int c) => l >= 0 && l < Tam && c >= 0 && c < Tam;
bool TemMina(int l, int c) => Dentro(l, c) && mina[l, c];
