    viz8.Count(v => TemMina(l + v.dl, c + v.dc));
int Abrir(int l, int c)
{
    var fila = new Queue<(int L, int C)>();
    fila.Enqueue((l, c));
    int abertas = 0;
    while (fila.Count > 0)
    {
        var (fl, fc) = fila.Dequeue();
        if (!Dentro(fl, fc) || aberta[fl, fc]) continue;
        aberta[fl, fc] = true;
        abertas++;
        if (Vizinhas(fl, fc) > 0) continue;
        foreach (var v in viz8) fila.Enqueue((fl + v.dl, fc + v.dc));
