static void GuardarMaior(ref int alvo, int valor)
{
    int visto = alvo;
    while (valor > visto)
    {
        int real = Interlocked.CompareExchange(ref alvo, valor, visto);
        if (real == visto) return;   // ganhei a troca
        visto = real;                // alguém mudou antes: tenta de novo
    }
}

