class Conta(int id, decimal saldo)
{
    public int Id => id;
    public decimal Saldo { get; set; } = saldo;
    public Lock Trava { get; } = new();
}
var ana = new Conta(1, 500m);
var bruno = new Conta(2, 300m);

bool TentarTransferir(Conta de, Conta para, decimal valor)
{
    lock (de.Trava)
    {
        Thread.Sleep(50);
        if (!para.Trava.TryEnter(200)) return false;
        de.Saldo -= valor;
        para.Saldo += valor;
        para.Trava.Exit();
        return true;
    }
}

var ida = Task.Run(() => TentarTransferir(ana, bruno, 100m));
var volta = Task.Run(() => TentarTransferir(bruno, ana, 50m));
bool[] deram = await Task.WhenAll(ida, volta);
Console.WriteLine(deram.All(d => d) ? "ok" : "deadlock detectado");

void TransferirEmOrdem(Conta de, Conta para, decimal valor)
{
    var (menor, maior) = de.Id < para.Id ? (de, para) : (para, de);
    lock (menor.Trava)
    {
        lock (maior.Trava)
        {
            de.Saldo -= valor;
            para.Saldo += valor;
        }
    }
}

var carla = new Conta(3, 800m);
var davi = new Conta(4, 200m);
await Task.WhenAll(
    Task.Run(() => TransferirEmOrdem(carla, davi, 100m)),
    Task.Run(() => TransferirEmOrdem(davi, carla, 50m)));

