class Placar
{
    private readonly Lock _trava = new();
    private readonly Dictionary<string, int> _pontos = [];
    private int _eventos;
    private int _vidasPerdidas;

    public int Eventos => Volatile.Read(ref _eventos);
    public int VidasPerdidas => Volatile.Read(ref _vidasPerdidas);

    public void Pontuar(string jogador, int valor)
    {
        Interlocked.Increment(ref _eventos);
        lock (_trava)
        {
            _pontos.TryGetValue(jogador, out int atual);
            _pontos[jogador] = atual + valor;
        }
    }

    public void PerderVida()
    {
        Interlocked.Increment(ref _eventos);
        Interlocked.Increment(ref _vidasPerdidas);
    }

    public List<(string Nome, int Pontos)> Ranking()
    {
        lock (_trava)
        {
            return _pontos.OrderByDescending(p => p.Value)
                .Select(p => (p.Key, p.Value))
                .ToList();
        }
    }
}

using System.Collections.Concurrent;
using System.Threading.Channels;

var fila = Channel.CreateBounded<Pedido>(new BoundedChannelOptions(4)
{
    FullMode = BoundedChannelFullMode.Wait
});
int processados = 0;
long centavos = 0;
var porCidade = new ConcurrentDictionary<string, int>();

async Task SepararAsync()
{
    await foreach (Pedido p in fila.Reader.ReadAllAsync())
    {
        await Task.Delay(p.Itens * 3);
        Interlocked.Increment(ref processados);
        Interlocked.Add(ref centavos, (long)(p.Valor * 100));
        porCidade.AddOrUpdate(p.Cidade, 1, (_, n) => n + 1);
    }
}

Task[] separadores = [SepararAsync(), SepararAsync(), SepararAsync()];
string[] cidades = ["Recife", "Fortaleza", "Salvador"];
for (int i = 1; i <= 30; i++)
{
    decimal valor = 19.90m * (i % 4 + 1);
    var pedido = new Pedido(i, cidades[i % 3], i % 5 + 1, valor);
    await fila.Writer.WriteAsync(pedido);
}
fila.Writer.Complete();
await Task.WhenAll(separadores);

Console.WriteLine($"Pedidos processados: {processados}");
foreach (var (cidade, total) in porCidade.OrderBy(c => c.Key))
    Console.WriteLine($"  {cidade,-10} {total} pedidos");
Console.WriteLine($"Faturamento: {centavos / 100m:C}");
Console.WriteLine($"Ticket médio: {centavos / 100m / processados:C}");

