using System.Collections.Concurrent;

string[] regioes = ["Floresta", "Deserto", "Pântano", "Montanha",
    "Praia", "Caverna", "Vulcão", "Geleira"];
var mapas = new ConcurrentDictionary<string, Mapa>();
int gerando = 0, pico = 0;
Lock medidor = new();
var opcoes = new ParallelOptions { MaxDegreeOfParallelism = 3 };

await Parallel.ForEachAsync(regioes, opcoes, async (regiao, ct) =>
{
    lock (medidor) pico = Math.Max(pico, ++gerando);
    var dado = new Random(regiao.Sum(letra => letra));
    char[] linha = new char[24];
    int agua = 0, tesouros = 0;
    for (int x = 0; x < linha.Length; x++)
    {
        int sorteio = dado.Next(100);
        linha[x] = sorteio < 25 ? '~' : sorteio < 35 ? '^' : '.';
        if (sorteio < 25) agua++;
        if (sorteio >= 97)
        {
            linha[x] = '$';
            tesouros++;
        }
    }
    await Task.Delay(30, ct);
    string faixa = new(linha);
    mapas[regiao] = new Mapa(regiao, faixa, agua, tesouros);
    lock (medidor) gerando--;
});

foreach (var m in mapas.Values.OrderBy(m => m.Regiao))
{
    Console.WriteLine($"{m.Regiao,-9} {m.Faixa}  água {m.Agua,2}" +
        $"  tesouros {m.Tesouros}");
}
Console.WriteLine($"Mapas gerados: {mapas.Count}");
Console.WriteLine($"Pico de gerações simultâneas: {pico}");

record Mapa(string Regiao, string Faixa, int Agua, int Tesouros);

