        public static Point operator +(Point a, Point b) =>
            new(a.X + b.X, a.Y + b.Y);

        public static Point operator *(Point p, int fator) =>
            new(p.X * fator, p.Y * fator);
    }

    extension(Point p)
    {
        public string Texto => $"({p.X}, {p.Y})";
        public Point EspelhoY => new(-p.X, p.Y);

        public int Quadrante => (p.X, p.Y) switch
        {
            (0, _) or (_, 0) => 0,
            (> 0, > 0) => 1,
            (< 0, > 0) => 2,
            (< 0, < 0) => 3,
            _ => 4,
        };

        public double Distancia(Point outro)
        {
            int dx = outro.X - p.X;
            int dy = outro.Y - p.Y;
            return Math.Sqrt(dx * dx + dy * dy);
        }
    }
}

