class Catraca(string portao, int capacidade, HashSet<string> setores)
{
    public int Publico { get; private set; }
    public int Barrados { get; private set; }
    public decimal Arrecadado { get; private set; }
    public bool Lotado => Publico >= capacidade;

    public void operator +=(Ingresso ingresso)
    {
        string? motivo = ingresso.Setor switch
        {
            _ when Lotado => "portão lotado",
            var s when !setores.Contains(s) => $"setor {s} não é aqui",
            _ => null,
        };
        if (motivo is not null)
        {
            Barrados++;
            Console.WriteLine($"X {ingresso.Torcedor}: {motivo}");
            return;
        }
        Publico++;
        Arrecadado += ingresso.Preco;
        Console.WriteLine($"+ {ingresso.Torcedor}, {ingresso.Setor}");
    }

    public void operator ++()
    {
        if (Lotado)
        {
            Barrados++;
            return;
        }
        Publico++;
        Console.WriteLine("+ cortesia (criança de colo)");
    }

    public void operator --() => Publico = Math.Max(0, Publico - 1);

    public string Resumo() => $"""
        Portão {portao}: {Publico} de {capacidade} pessoas
        Barrados: {Barrados}
        Arrecadado: {Arrecadado:C}
        """;
