int BuscaLinear(int[] v, int alvo)
{
    for (int i = 0; i < v.Length; i++)
    {
        if (v[i] == alvo) return i;
    }
    return -1;
}

int BuscaBinaria(int[] v, int alvo)
{
    int lo = 0, hi = v.Length - 1;
    while (lo <= hi)
    {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] == alvo) return mid;
        if (v[mid] < alvo) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int Palpites(int secreto, int min, int max)
{
    for (int palpite = 1; min <= max; palpite++)
    {
        int chute = min + (max - min) / 2;
        if (chute == secreto) return palpite;
        if (chute < secreto) min = chute + 1;
        else max = chute - 1;
    }
    return -1;
}

int PrimeiraPosicao(int[] v, int alvo)
{
    int lo = 0, hi = v.Length;
    while (lo < hi)
    {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] < alvo) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

