int[] Intercalar(int[] a, int[] b)
{
    var r = new int[a.Length + b.Length];
    int i = 0, j = 0, k = 0;
    while (i < a.Length && j < b.Length)
    {
        r[k++] = a[i] <= b[j] ? a[i++] : b[j++];
    }
    while (i < a.Length) r[k++] = a[i++];
    while (j < b.Length) r[k++] = b[j++];
    return r;
}

int nivelMax = 0;
int[] MergeSort(int[] v, int nivel)
{
    nivelMax = Math.Max(nivelMax, nivel);
    if (v.Length <= 1) return v;
    int meio = v.Length / 2;
    int[] esq = MergeSort(v[..meio], nivel + 1);
    int[] dir = MergeSort(v[meio..], nivel + 1);
    return Intercalar(esq, dir);
}

int Particionar(int[] v, int ini, int fim)
{
    int pivo = v[fim], i = ini;
    for (int j = ini; j < fim; j++)
    {
        if (v[j] >= pivo) continue;
        (v[i], v[j]) = (v[j], v[i]);
        i++;
    }
    (v[i], v[fim]) = (v[fim], v[i]);
    return i;
}

