int fundoQuick = 0;
void QuickSort(int[] v, int ini, int fim, int nivel)
{
    fundoQuick = Math.Max(fundoQuick, nivel);
    if (ini >= fim) return;
    int p = Particionar(v, ini, fim);
    QuickSort(v, ini, p - 1, nivel + 1);
    QuickSort(v, p + 1, fim, nivel + 1);
}

