    public int Valor { get; } = valor;
    public NoArvore? Esquerda { get; set; }
    public NoArvore? Direita { get; set; }
}

NoArvore Inserir(NoArvore? raiz, int valor)
{
    if (raiz is null) return new NoArvore(valor);
    if (valor < raiz.Valor) raiz.Esquerda = Inserir(raiz.Esquerda, valor);
    else raiz.Direita = Inserir(raiz.Direita, valor);
    return raiz;
}

IEnumerable<int> Percorrer(NoArvore? no, string ordem)
{
    if (no is null) yield break;
    if (ordem == "pre") yield return no.Valor;
    foreach (int v in Percorrer(no.Esquerda, ordem)) yield return v;
    if (ordem == "em") yield return no.Valor;
    foreach (int v in Percorrer(no.Direita, ordem)) yield return v;
    if (ordem == "pos") yield return no.Valor;
}

bool Contem(NoArvore? no, int alvo)
{
    while (no is not null && no.Valor != alvo)
    {
        no = alvo < no.Valor ? no.Esquerda : no.Direita;
    }
    return no is not null;
}

int Altura(NoArvore? n) =>
    n is null ? 0 : 1 + Math.Max(Altura(n.Esquerda), Altura(n.Direita));
NoArvore? torta = null;
for (int i = 1; i <= 7; i++) torta = Inserir(torta, i);
Console.WriteLine($"Altura: {Altura(raiz)} x {Altura(torta)} (torta)");

