void Subir(int i)
{
    int pai = (i - 1) / 2;
    if (i == 0 || heap[pai] <= heap[i]) return;
    (heap[i], heap[pai]) = (heap[pai], heap[i]);
    Subir(pai);
}
void Push(int valor)
{
    heap.Add(valor);
    Subir(heap.Count - 1);
}

void Descer(int i)
{
    while (true)
    {
        int menor = i, e = 2 * i + 1, d = 2 * i + 2;
        if (e < heap.Count && heap[e] < heap[menor]) menor = e;
        if (d < heap.Count && heap[d] < heap[menor]) menor = d;
        if (menor == i) return;
        (heap[i], heap[menor]) = (heap[menor], heap[i]);
        i = menor;
    }
}

int Pop()
{
    int topo = heap[0];
    heap[0] = heap[^1];
    heap.RemoveAt(heap.Count - 1);
    Descer(0);
    return topo;
}

int[] MaioresK(int[] v, int k)
{
    var fila = new PriorityQueue<int, int>();
    foreach (int x in v)
    {
        fila.Enqueue(x, x);
        if (fila.Count > k) fila.Dequeue();
    }
    return [.. fila.UnorderedItems.Select(p => p.Element).OrderDescending()];
}

var baixa = new PriorityQueue<int, int>();
var alta = new PriorityQueue<int, int>();
void AdicionarLeitura(int x)
{
    baixa.Enqueue(x, -x);
    int topo = baixa.Dequeue();
    alta.Enqueue(topo, topo);
    if (alta.Count <= baixa.Count) return;
    topo = alta.Dequeue();
    baixa.Enqueue(topo, -topo);
}

double Mediana() => baixa.Count > alta.Count
    ? baixa.Peek() : (baixa.Peek() + alta.Peek()) / 2.0;
int[] pings = [40, 12, 90, 33, 25];
foreach (int ms in pings)
{
    AdicionarLeitura(ms);
    Console.WriteLine($"+{ms} ms: mediana {Mediana()}");
}

