void Estrada(string a, string b, int minutos)
{
    estradas.TryAdd(a, []);
    estradas.TryAdd(b, []);
    estradas[a].Add((b, minutos));
    estradas[b].Add((a, minutos));
}

Estrada("Centro", "Porto", 7);
Estrada("Centro", "Lagoa", 9);
Estrada("Centro", "Serra", 14);
Estrada("Porto", "Lagoa", 10);
Estrada("Porto", "Praia", 15);
Estrada("Lagoa", "Praia", 11);
Estrada("Lagoa", "Serra", 2);
Estrada("Serra", "Praia", 6);

var tempo = new Dictionary<string, int>();
var veioDe = new Dictionary<string, string>();
var fila = new PriorityQueue<string, int>();

void Relaxar(string de, string para, int custo)
{
    int novo = tempo[de] + custo;
    if (tempo.TryGetValue(para, out int atual) && atual <= novo) return;
    tempo[para] = novo;
    veioDe[para] = de;
    fila.Enqueue(para, novo);
}

while (fila.TryDequeue(out var lugar, out int t))
{
    if (t > tempo[lugar]) continue;
    foreach (var (vizinho, minutos) in estradas[lugar])
    {
        Relaxar(lugar, vizinho, minutos);
    }
}

List<string> Rota(string destino)
{
    var rota = new List<string> { destino };
    while (veioDe.TryGetValue(rota[^1], out var ant)) rota.Add(ant);
    rota.Reverse();
    return rota;
}

