bool SomaExata(int i, int restante, List<int> usadas)
{
    nos++;
    if (restante == 0) return true;
    if (restante < 0 || i == duracoes.Length) return false;
    usadas.Add(duracoes[i]);
    if (SomaExata(i + 1, restante - duracoes[i], usadas)) return true;
    usadas.RemoveAt(usadas.Count - 1);
