bool Segura(int[] cols, int linha, int c)
{
    for (int l = 0; l < linha; l++)
    {
        if (cols[l] == c || Math.Abs(cols[l] - c) == linha - l) return false;
    }
    return true;
}

int Rainhas(int n, int linha, int[] cols)
{
    if (linha == n) return 1;
    int total = 0;
    for (int c = 0; c < n; c++)
    {
        cols[linha] = c;
        if (Segura(cols, linha, c)) total += Rainhas(n, linha + 1, cols);
    }
    return total;
}
