public interface ICotacao
{
    decimal Preco(string produto);
}

public class CotacaoFornecedor : ICotacao
{
    private readonly Dictionary<string, decimal> _precos =
        new() { ["café"] = 18.9m, ["açúcar"] = 5.49m };

    public decimal Preco(string produto)
    {
        Console.WriteLine($"  (consultando fornecedor: {produto})");
        return _precos[produto];
    }
}

public class CotacaoComCache(ICotacao interna) : ICotacao
{
    private readonly Dictionary<string, decimal> _cache = [];

    public decimal Preco(string produto)
    {
        if (!_cache.TryGetValue(produto, out var preco))
            _cache[produto] = preco = interna.Preco(produto);
        return preco;
    }
}

