public class Produto(int id, string nome, int quantidade, decimal custo)
{
    public int Id { get; } = id;
    public string Nome { get; } = nome;
    public int Quantidade { get; } = quantidade;
    public decimal CustoInterno { get; } = custo;
}

public partial class Estoque
{
    private readonly ConcurrentDictionary<int, Produto> _itens = new();
    private int _ultimoId;

    public IEnumerable<Produto> Todos => _itens.Values;
    public Produto? Buscar(int id) => _itens.GetValueOrDefault(id);
    public bool Remover(int id) => _itens.TryRemove(id, out _);
}

public partial class Estoque
{
    public void Salvar(Produto p) => _itens[p.Id] = p;

    public Produto Criar(ProdutoEntrada e)
    {
        var id = Interlocked.Increment(ref _ultimoId);
        var p = new Produto(id, e.Nome, e.Quantidade, e.Custo);
        Salvar(p);
        return p;
    }
}

static ProdutoSaida ParaSaida(Produto p) =>
    new(p.Id, p.Nome, p.Quantidade);

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<Estoque>();
var app = builder.Build();
var produtos = app.MapGroup("/produtos").WithTags("Estoque");

produtos.MapPost("/", (ProdutoEntrada entrada, Estoque e) =>
{
    var p = e.Criar(entrada);
    return TypedResults.Created($"/produtos/{p.Id}", ParaSaida(p));
});

Results<NoContent, NotFound> Substituir(int id, ProdutoEntrada x,
    Estoque e)
{
    if (e.Buscar(id) is null) return TypedResults.NotFound();
    e.Salvar(new Produto(id, x.Nome, x.Quantidade, x.Custo));
    return TypedResults.NoContent();
}
produtos.MapPut("/{id:int}", Substituir);
produtos.MapDelete("/{id:int}", (int id, Estoque e) =>
    e.Remover(id) ? Results.NoContent() : Results.NotFound());

