public class Pedido
{
    public TipoCliente Tipo { get; set; }
    public string Documento { get; set; } = "";
    public List<ItemPedido> Itens { get; set; } = [];
    public Cobranca Cobranca { get; set; } = new("Pix", null);
}

public class ItemValidator : AbstractValidator<ItemPedido>
{
    static readonly string[] Catalogo = ["Café", "Pão", "Bolo"];

    public ItemValidator()
    {
        RuleFor(i => i.Produto).Must(p => Catalogo.Contains(p))
            .WithMessage("'{PropertyValue}' não está no catálogo");
        RuleFor(i => i.Quantidade).InclusiveBetween(1, 10);
    }
}

public static class CuponsDb
{
    public static async Task<bool> ExisteAsync(string? codigo,
        CancellationToken ct)
    {
        await Task.Delay(5, ct); // finge ir ao banco
        return codigo is "BEMVINDO10" or "FRETEGRATIS";
    }
}

public class CobrancaValidator : AbstractValidator<Cobranca>
{
    public CobrancaValidator()
    {
        RuleFor(c => c.Cupom).MustAsync(CuponsDb.ExisteAsync)
            .When(c => c.Cupom is not null)
            .WithMessage("Cupom {PropertyValue} não existe");
    }
}

public class PedidoValidator : AbstractValidator<Pedido>
{
    public PedidoValidator()
    {
        RuleFor(p => p.Documento).Length(11)
            .When(p => p.Tipo == TipoCliente.PessoaFisica);
        RuleFor(p => p.Documento).Length(14)
            .Unless(p => p.Tipo == TipoCliente.PessoaFisica);
        RuleForEach(p => p.Itens).SetValidator(new ItemValidator());
        RuleFor(p => p.Cobranca).SetValidator(new CobrancaValidator());
    }
}

servicos.AddValidatorsFromAssemblyContaining<PedidoValidator>();
using var provedor = servicos.BuildServiceProvider();
var validador = provedor.GetRequiredService<IValidator<Pedido>>();

