{
    Tipo = TipoCliente.PessoaJuridica, Documento = "123",
    Itens = [new("Café", 2), new("Picanha", 0)],
    Cobranca = new("Pix", "NATAL50"),
};
var r = await validador.ValidateAsync(pedido);
foreach (var e in r.Errors)
{
    Console.WriteLine($"{e.PropertyName}: {e.ErrorMessage}");
}

try
{
    validador.Validate(pedido);
}
catch (AsyncValidatorInvokedSynchronouslyException)
{
    Console.WriteLine("Regra assíncrona exige ValidateAsync");
}

