using Bogus;
using Spectre.Console;

string[] vendedores = ["Ana", "Bruno", "Carla", "Diego"];
string[] itens = ["Café", "Bolo de milho", "Pão de queijo", "Suco"];

var faker = new Faker<Venda>("pt_BR")
    .UseSeed(34)
    .CustomInstantiator(f => new Venda(
        f.PickRandom(vendedores),
        f.PickRandom(itens),
        f.Random.Int(1, 5),
        f.Finance.Amount(4, 30)));
var vendas = faker.Generate(40);

var ranking = vendas
    .GroupBy(v => v.Vendedor)
    .Select(g => new
    {
        Vendedor = g.Key,
        Itens = g.Sum(v => v.Qtd),
        Total = g.Sum(v => v.Qtd * v.Preco),
    })
    .OrderByDescending(r => r.Total)
    .ToList();

AnsiConsole.Write(new Rule("[yellow]Vendas da semana[/]"));
var tabela = new Table()
    .Border(TableBorder.Rounded)
    .AddColumn("Vendedor")
    .AddColumn(new TableColumn("Itens").RightAligned())
    .AddColumn(new TableColumn("Total").RightAligned());
foreach (var r in ranking)
{
    tabela.AddRow(r.Vendedor, r.Itens.ToString(), $"{r.Total:C}");
}
AnsiConsole.Write(tabela);

var grafico = new BarChart().Width(50).Label("Total por vendedor");
foreach (var r in ranking)
{
    var valor = (double)Math.Round(r.Total);
    grafico.AddItem(r.Vendedor, valor, Color.Green);
}
AnsiConsole.Write(grafico);

var campeao = vendas.GroupBy(v => v.Produto)
    .MaxBy(g => g.Sum(v => v.Qtd))!;
var faturamento = vendas.Sum(v => v.Qtd * v.Preco);
AnsiConsole.Write(new Panel(
        $"Produto campeão: [green]{campeao.Key}[/]\n" +
        $"Faturamento: [bold]{faturamento:C}[/]")
    .Header("Resumo"));

public record Venda(
    string Vendedor, string Produto, int Qtd, decimal Preco);

using Dapper;
using FluentValidation;
using Microsoft.Data.Sqlite;

using var db = new SqliteConnection("Data Source=:memory:");
db.Open();
db.Execute(
    "CREATE TABLE Matriculas (Nome TEXT, Email TEXT, Curso TEXT)");

List<Pedido> pedidos =
[
    new("Luana Costa", "luana@escola.com", "C#"),
    new("", "sem-arroba", "C#"),
    new("Igor Lima", "igor@escola.com", "Culinária"),
    new("Beatriz Souza", "bia@escola.com", "Jogos"),
    new("Luana C.", "luana@escola.com", "Web"),
    new("Tiago Rocha", "tiago@escola.com", "C#"),
];

var validador = new PedidoValidator(db);
foreach (var p in pedidos)
{
    var r = validador.Validate(p);
    if (!r.IsValid)
    {
        var motivos = string.Join("; ",
            r.Errors.Select(e => e.ErrorMessage));
        Console.WriteLine($"RECUSADO {p.Email}: {motivos}");
        continue;
    }
    db.Execute(
        "INSERT INTO Matriculas VALUES (@Nome, @Email, @Curso)", p);
    Console.WriteLine($"OK       {p.Nome} em {p.Curso}");
}

Console.WriteLine("\nTurmas:");
var turmas = db.Query<Turma>("""
    SELECT Curso, COUNT(*) AS Alunos FROM Matriculas
    GROUP BY Curso ORDER BY Alunos DESC, Curso
    """);
foreach (var t in turmas)
{
    Console.WriteLine($"  {t.Curso,-6} {t.Alunos} aluno(s)");
}

public record Pedido(string Nome, string Email, string Curso);
public record Turma(string Curso, long Alunos);

public class PedidoValidator : AbstractValidator<Pedido>
{
    public PedidoValidator(SqliteConnection db)
    {
        RuleFor(p => p.Nome).NotEmpty().WithMessage("nome vazio");
        RuleFor(p => p.Email).EmailAddress()
            .WithMessage("e-mail inválido")
            .Must(email => db.ExecuteScalar<int>(
                "SELECT COUNT(*) FROM Matriculas WHERE Email = @e",
                new { e = email }) == 0)
            .WithMessage("e-mail já matriculado");
        RuleFor(p => p.Curso).Must(c => c is "C#" or "Web" or "Jogos")
            .WithMessage("curso {PropertyValue} não existe");
    }
}

using System.Globalization;
using Humanizer;
using MediatR;
using Microsoft.Extensions.DependencyInjection;
using Serilog;

Log.Logger = new LoggerConfiguration()
    .WriteTo.Console(
        outputTemplate: "[{Level:u3}] {Message:lj}{NewLine}",
        formatProvider: new CultureInfo("pt-BR"))
    .CreateLogger();

var mediador = new ServiceCollection()
    .AddMediatR(c => c.RegisterServicesFromAssemblyContaining<Jogo>())
    .BuildServiceProvider()
    .GetRequiredService<IMediator>();

List<Jogo> carrinho =
[
    new("Hades", 73.99m), new("Celeste", 36.99m), new("Balatro", 49m),
];
await mediador.Send(new Fechar("Rafa", carrinho));
await mediador.Send(new Fechar("Duda", [new("Terraria", 19.99m)]));
Log.CloseAndFlush();

public record Jogo(string Titulo, decimal Preco);
public record Fechar(string Cliente, List<Jogo> Jogos) : IRequest;
public record PedidoFechado(string Cliente, int Qtd) : INotification;

public class FecharHandler(IPublisher publicador)
    : IRequestHandler<Fechar>
{
    public async Task Handle(Fechar r, CancellationToken ct)
    {
        var total = r.Jogos.Sum(j => j.Preco);
        Log.Information("Pedido de {Cliente}: {Total:C}",
            r.Cliente, total);
        var evento = new PedidoFechado(r.Cliente, r.Jogos.Count);
        await publicador.Publish(evento, ct);
    }
}

public class Recibo : INotificationHandler<PedidoFechado>
{
    public Task Handle(PedidoFechado n, CancellationToken ct)
    {
        var jogos = "jogo".ToQuantity(n.Qtd, ShowQuantityAs.Words);
        Log.Information("Recibo: {Cliente} levou {Jogos}",
            n.Cliente, jogos);
        return Task.CompletedTask;
    }
}

public class Conquistas : INotificationHandler<PedidoFechado>
{
    public Task Handle(PedidoFechado n, CancellationToken ct)
    {
        if (n.Qtd >= 3)
        {
            Log.Warning("{Cliente} ganhou: Colecionador", n.Cliente);
        }
        return Task.CompletedTask;
    }
}

