using UnityEngine;
using UnityEngine.InputSystem;

[RequireComponent(typeof(Rigidbody2D))]
public class Corredor : MonoBehaviour
{
    private const string Chave = "recorde_moedas";
    [SerializeField] private float velocidade = 6f;
    [SerializeField] private float pulo = 9f;
    [SerializeField] private LayerMask chao;
    private Rigidbody2D _rb;
    private Vector2 _checkpoint;
    private float _eixo;
    private bool _querPular;
    private int _moedas;

    private void Awake() => _rb = GetComponent<Rigidbody2D>();

    private void Start() => _checkpoint = _rb.position;

    private void Update()
    {
        Keyboard k = Keyboard.current;
        if (k == null) return;
        _eixo = k.dKey.isPressed ? 1f : k.aKey.isPressed ? -1f : 0f;
        if (k.spaceKey.wasPressedThisFrame) _querPular = true;
    }

    private void FixedUpdate()
    {
        _rb.linearVelocityX = _eixo * velocidade;
        bool noChao = Physics2D.Raycast(
            _rb.position, Vector2.down, 0.6f, chao);
        if (_querPular && noChao)
            _rb.AddForce(Vector2.up * pulo, ForceMode2D.Impulse);
        _querPular = false;
    }

    private void OnTriggerEnter2D(Collider2D outro)
    {
        if (outro.CompareTag("Checkpoint"))
            _checkpoint = outro.transform.position;
        else if (outro.CompareTag("Moeda"))
        {
            _moedas++;
            Destroy(outro.gameObject);
        }
        else if (outro.CompareTag("Abismo"))
        {
            _rb.position = _checkpoint;
            _rb.linearVelocity = Vector2.zero;
        }
        else if (outro.CompareTag("Chegada")) Terminar();
    }

    private void Terminar()
    {
        int recorde = PlayerPrefs.GetInt(Chave, 0);
        if (_moedas > recorde) PlayerPrefs.SetInt(Chave, _moedas);
        int melhor = Mathf.Max(_moedas, recorde);
        Debug.Log($"Fim! {_moedas} moedas, recorde {melhor}");
    }
}

