public class Teclado
{
    private KeyboardState _anterior, _atual;

    public void Atualizar()
    {
        _anterior = _atual;
        _atual = Keyboard.GetState();
    }
    public bool Apertou(Keys k) =>
        _atual.IsKeyDown(k) && _anterior.IsKeyUp(k);
}

public class Raquete
{
    public Rectangle Area = new(360, 440, 80, 12);

    public void Mover(KeyboardState teclado, float dt)
    {
        int passo = (int)(400 * dt);
        if (teclado.IsKeyDown(Keys.Left)) Area.X -= passo;
        if (teclado.IsKeyDown(Keys.Right)) Area.X += passo;
        Area.X = MathHelper.Clamp(Area.X, 0, 800 - Area.Width);
    }
}

public static class Rebote
{
    public static Parte Onde(Rectangle raquete, float xBola)
    {
        float terco = raquete.Width / 3f;
        if (xBola < raquete.Left + terco) return Parte.Esquerda;
        return xBola < raquete.Right - terco
            ? Parte.Meio : Parte.Direita;
    }
}

public static class Regras
{
    public static int Acertar(List<Bloco> blocos, Rectangle bola)
    {
        int i = blocos.FindIndex(b => b.Area.Intersects(bola));
        if (i < 0) return 0;
        int pontos = blocos[i].Pontos;
        blocos.RemoveAt(i);
        return pontos;
    }
}

public class Bola
{
    public Vector2 Posicao { get; set; } = new(400, 300);
    public Vector2 Velocidade { get; set; } = new(180, -240);
    public void Mover(GameTime tempo)
    {
        float dt = (float)tempo.ElapsedGameTime.TotalSeconds;
        Posicao += Velocidade * dt;
        if (Posicao.Y < 0)
            Velocidade = Vector2.Reflect(Velocidade, Vector2.UnitY);
    }
}

public class BotaoTela
{
    public Rectangle Area { get; init; }
    private ButtonState _antes = ButtonState.Released;
    public bool Clicado(MouseState mouse)
    {
        bool agora = mouse.LeftButton == ButtonState.Pressed;
        bool clicou = agora && _antes == ButtonState.Released;
        _antes = mouse.LeftButton;
        return clicou && Area.Contains(mouse.Position);
    }
}

