public class Combo
{
    private const double Janela = 1.5;
    private double _ultimo = double.NegativeInfinity;
    public int Atual { get; private set; }
    public int Acertar(double agora)
    {
        Atual = agora - _ultimo <= Janela ? Atual + 1 : 1;
        _ultimo = agora;
        return Atual * 10;
    }
}

public class Conquistas
{
    public event Action<Conquista> Liberou;
    private readonly HashSet<string> _feitas = [];

    public void Registrar(Conquista c, int progresso)
    {
        if (progresso < c.Meta || !_feitas.Add(c.Id)) return;
        Liberou?.Invoke(c);
    }
}

public partial class HudCombo
{
    private readonly Combo _combo = new();

    public void AoAcertar()
    {
        double agora = Time.GetTicksMsec() / 1000.0;
        int pontos = _combo.Acertar(agora);
        Text = $"x{_combo.Atual} +{pontos}";
    }
}

public class PlacarMonoGame
{
    private readonly Combo _combo = new();

    public string Acertar(Xna.GameTime tempo)
    {
        double agora = tempo.TotalGameTime.TotalSeconds;
        int pontos = _combo.Acertar(agora);
        return $"x{_combo.Atual} +{pontos}";
    }
}

public static class TesteCombo
{
    public static bool JanelaFunciona()
    {
        var combo = new Combo();
        combo.Acertar(0.0);
        combo.Acertar(1.0);
        int depois = combo.Acertar(5.0);
        return combo.Atual == 1 && depois == 10;
    }
}

