using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using Microsoft.Xna.Framework.Input;

public class Pong : Game
{
    private const int Largura = 800, Altura = 480;
    private SpriteBatch _pincel;
    private Texture2D _pixel;
    private Rectangle _esq = new(20, 200, 12, 80);
    private Rectangle _dir = new(768, 200, 12, 80);
    private Vector2 _bola = new(400, 240), _vel = new(260, 180);
    private int _pontosEsq, _pontosDir;

    public Pong() => _ = new GraphicsDeviceManager(this);
    private Rectangle Bola => new((int)_bola.X, (int)_bola.Y, 10, 10);

    protected override void LoadContent()
    {
        _pincel = new SpriteBatch(GraphicsDevice);
        _pixel = new Texture2D(GraphicsDevice, 1, 1);
        _pixel.SetData(new[] { Color.White });
    }

    protected override void Update(GameTime gameTime)
    {
        float dt = (float)gameTime.ElapsedGameTime.TotalSeconds;
        var k = Keyboard.GetState();
        int passo = (int)(360 * dt);
        if (k.IsKeyDown(Keys.W)) _esq.Y -= passo;
        if (k.IsKeyDown(Keys.S)) _esq.Y += passo;
        if (k.IsKeyDown(Keys.Up)) _dir.Y -= passo;
        if (k.IsKeyDown(Keys.Down)) _dir.Y += passo;
        _esq.Y = MathHelper.Clamp(_esq.Y, 0, Altura - _esq.Height);
        _dir.Y = MathHelper.Clamp(_dir.Y, 0, Altura - _dir.Height);
        _bola += _vel * dt;
        if (_bola.Y < 0 || _bola.Y > Altura - 10) _vel.Y = -_vel.Y;
        if (Bola.Intersects(_vel.X < 0 ? _esq : _dir))
            _vel.X *= -1.05f;
        if (_bola.X < 0) Ponto(ref _pontosDir);
        if (_bola.X > Largura) Ponto(ref _pontosEsq);
        base.Update(gameTime);
    }

    private void Ponto(ref int placar)
    {
        placar++;
        _bola = new Vector2(Largura / 2, Altura / 2);
        _vel = new Vector2(_vel.X > 0 ? -260 : 260, 180);
        Window.Title = $"Pong  {_pontosEsq} x {_pontosDir}";
    }

    protected override void Draw(GameTime gameTime)
    {
        GraphicsDevice.Clear(Color.Black);
        _pincel.Begin();
        foreach (var r in new[] { _esq, _dir, Bola })
            _pincel.Draw(_pixel, r, Color.White);
        _pincel.End();
        base.Draw(gameTime);
    }
}

