public partial class Gerador : Node2D
{
    [Export] public PackedScene CenaMorcego { get; set; }
    [Export(PropertyHint.Range, "1,50,1")]
    public int Limite { get; set; } = 12;
    [Export] public ulong Semente { get; set; } = 7;

    private readonly Timer _relogio = new() { WaitTime = 2.0 };
    private readonly RandomNumberGenerator _rng = new();
    private int _onda;

    public override void _Ready()
    {
        _rng.Seed = Semente;
        AddChild(_relogio);
        _relogio.Timeout += Gerar;
        _relogio.Start();
    }

    private void Gerar()
    {
        int vivos = GetTree().GetNodesInGroup("inimigos").Count;
        if (vivos >= Limite) return;
        var morcego = CenaMorcego.Instantiate<Morcego>();
        float angulo = _rng.RandfRange(0f, Mathf.Tau);
        morcego.Position = Vector2.Right.Rotated(angulo) * 400f;
        morcego.Velocidade += _onda * 10f;
        AddChild(morcego);
        _onda++;
        _relogio.WaitTime = Mathf.Max(0.5, _relogio.WaitTime * 0.95);
    }
}

