sealed class BufferNativo : IDisposable
{
    private IntPtr _ptr;
    public BufferNativo(int bytes) => _ptr = Marshal.AllocHGlobal(bytes);
    ~BufferNativo() => Liberar();   // rede de segurança
    public void Dispose()
    {
        Liberar();
        GC.SuppressFinalize(this);  // já liberei: não precisa finalizar
    }
    private void Liberar()
    {
        if (_ptr == IntPtr.Zero) return;
        Marshal.FreeHGlobal(_ptr);
        _ptr = IntPtr.Zero;
    }
}

