const string Fase = """
    fase=3;tempo=90;vidas=2
    #########
    #P..*..G#
    #.##.##.#
    #*..G...#
    #########
    """;

LerFase(Fase); // aquecimento: a 1a chamada inicializa caches do .NET
long antes = GC.GetAllocatedBytesForCurrentThread();
ResumoFase f = LerFase(Fase);
long bytes = GC.GetAllocatedBytesForCurrentThread() - antes;

Console.WriteLine($"Fase {f.Numero}: {f.Tempo} s, {f.Vidas} vidas");
Console.WriteLine($"Paredes: {f.Paredes}, pastilhas: {f.Pastilhas}");
Console.WriteLine($"Poderes: {f.Poderes}, fantasmas: {f.Fantasmas}");
Console.WriteLine($"Jogador em ({f.JogadorX}, {f.JogadorY})");
Console.WriteLine($"Alocações do leitor: {bytes} bytes");

static ResumoFase LerFase(ReadOnlySpan<char> texto)
{
    var r = new ResumoFase();
    int y = -1;
    foreach (ReadOnlySpan<char> linha in texto.EnumerateLines())
    {
        if (y++ < 0)
        {
            LerCabecalho(linha, ref r);
            continue;
        }
        for (int x = 0; x < linha.Length; x++)
        {
            switch (linha[x])
            {
                case '#': r.Paredes++; break;
                case '.': r.Pastilhas++; break;
                case '*': r.Poderes++; break;
                case 'G': r.Fantasmas++; break;
                case 'P': (r.JogadorX, r.JogadorY) = (x, y - 1); break;
            }
        }
    }
    return r;
}

static void LerCabecalho(ReadOnlySpan<char> linha, ref ResumoFase r)
{
    foreach (Range campo in linha.Split(';'))
    {
        ReadOnlySpan<char> par = linha[campo];
        int igual = par.IndexOf('=');
        int valor = int.Parse(par[(igual + 1)..]);
        switch (par[..igual])
        {
            case "fase": r.Numero = valor; break;
            case "tempo": r.Tempo = valor; break;
            case "vidas": r.Vidas = valor; break;
        }
    }
}

struct ResumoFase
{
    public int Numero, Tempo, Vidas, Paredes, Pastilhas;
    public int Poderes, Fantasmas, JogadorX, JogadorY;
}

using Microsoft.Extensions.ObjectPool;

var provedor = new DefaultObjectPoolProvider { MaximumRetained = 128 };
ObjectPool<Projetil> pool = provedor.Create<Projetil>();

long bytesSem = Simular(usarPool: false, pool);
int novosSem = Projetil.Criados;
Projetil.Criados = 0;
long bytesCom = Simular(usarPool: true, pool);
int novosCom = Projetil.Criados;

Console.WriteLine("600 quadros, 3 tiros por quadro (1800 disparos)");
Console.WriteLine($"Sem pool: {novosSem} projéteis, {bytesSem} bytes");
Console.WriteLine($"Com pool: {novosCom} projéteis, {bytesCom} bytes");
double economia = 1 - (double)bytesCom / bytesSem;
Console.WriteLine($"Economia de alocação: {economia:P1}");

static long Simular(bool usarPool, ObjectPool<Projetil> pool)
{
    var ativos = new List<Projetil>(128);
    long antes = GC.GetAllocatedBytesForCurrentThread();
    for (int quadro = 0; quadro < 600; quadro++)
    {
        for (int t = 0; t < 3; t++)
        {
            Projetil p = usarPool ? pool.Get() : new Projetil();
            p.Disparar(velocidade: 12 + t);
            ativos.Add(p);
        }
        for (int i = ativos.Count - 1; i >= 0; i--)
        {
            if (ativos[i].Mover()) continue;
            if (usarPool) pool.Return(ativos[i]);
            ativos.RemoveAt(i);
        }
    }
    return GC.GetAllocatedBytesForCurrentThread() - antes;
}

sealed class Projetil : IResettable
{
    public static int Criados;
    public float X { get; private set; }
    public float Velocidade { get; private set; }
    public Projetil() => Criados++;
    public void Disparar(float velocidade) => Velocidade = velocidade;
    public bool Mover() => (X += Velocidade) <= 240;
    public bool TryReset()
    {
        (X, Velocidade) = (0, 0);
        return true;
    }
}

