class TrocaParametro(ParameterExpression de, ParameterExpression para)
    : ExpressionVisitor
{
    protected override Expression VisitParameter(
        ParameterExpression node) => node == de ? para : node;
}

static partial class Filtros
{
    static Expression<Func<T, bool>> Juntar<T>(
        Expression<Func<T, bool>> a, Expression<Func<T, bool>> b,
        Func<Expression, Expression, BinaryExpression> operador)
    {
        var troca = new TrocaParametro(b.Parameters[0], a.Parameters[0]);
        var corpo = operador(a.Body, troca.Visit(b.Body));
        return Expression.Lambda<Func<T, bool>>(corpo, a.Parameters);
    }
}

static partial class Filtros
{
    public static Expression<Func<T, bool>> E<T>(
        this Expression<Func<T, bool>> a, Expression<Func<T, bool>> b)
        => Juntar(a, b, Expression.AndAlso);
    public static Expression<Func<T, bool>> Ou<T>(
        this Expression<Func<T, bool>> a, Expression<Func<T, bool>> b)
        => Juntar(a, b, Expression.OrElse);
}

