sealed class ObrigatorioAttribute : Attribute;
sealed class FaixaAttribute(int min, int max) : Attribute
{
    public int Min { get; } = min;
    public int Max { get; } = max;
}
sealed class ContemAttribute(string trecho) : Attribute
{
    public string Trecho { get; } = trecho;
}

static class Validador
{
    static readonly Dictionary<Type, PropertyInfo[]> Cache = new();

    public static List<string> Validar(object obj)
    {
        var tipo = obj.GetType();
        if (!Cache.TryGetValue(tipo, out var props))
            Cache[tipo] = props = tipo.GetProperties();
        var erros = new List<string>();
        foreach (var p in props)
        {
            var valor = p.GetValue(obj);
            if (p.IsDefined(typeof(ObrigatorioAttribute))
                && string.IsNullOrWhiteSpace(valor as string))
                erros.Add($"{p.Name} é obrigatório");
            if (p.GetCustomAttribute<FaixaAttribute>() is { } f
                && valor is int n && (n < f.Min || n > f.Max))
                erros.Add($"{p.Name} fora de {f.Min} a {f.Max}");
            if (p.GetCustomAttribute<ContemAttribute>() is { } c
                && valor is string s && !s.Contains(c.Trecho))
                erros.Add($"{p.Name} precisa conter '{c.Trecho}'");
        }
        return erros;
    }
}

