sealed class ServicoAttribute(Type contrato) : Attribute
{
    public Type Contrato { get; } = contrato;
    public bool Unico { get; init; }
}

sealed class Container
{
    readonly Dictionary<Type, (Type Impl, bool Unico)> _mapa = new();
    readonly Dictionary<Type, object> _unicos = new();

    public Container(Assembly assembly)
    {
        foreach (var t in assembly.GetTypes().OrderBy(t => t.Name))
        {
            if (t.GetCustomAttribute<ServicoAttribute>() is not { } s)
                continue;
            _mapa[s.Contrato] = (t, s.Unico);
            Console.WriteLine($"registro: {s.Contrato.Name} -> {t.Name}");
        }
    }

    public T Resolver<T>() => (T)Resolver(typeof(T));

    object Resolver(Type t)
    {
        var (impl, unico) = _mapa.GetValueOrDefault(t, (t, false));
        if (unico && _unicos.TryGetValue(impl, out var pronto))
            return pronto;
        var ctor = impl.GetConstructors()
            .MaxBy(c => c.GetParameters().Length)!;
        var args = ctor.GetParameters()
            .Select(p => Resolver(p.ParameterType)).ToArray();
        var nomes = args.Select(a => a.GetType().Name);
        Console.WriteLine($"new {impl.Name}({string.Join(", ", nomes)})");
        var obj = ctor.Invoke(args);
        if (unico) _unicos[impl] = obj;
        return obj;
    }
}

