using System.Globalization;
using System.Linq.Expressions;

var livros = new List<Livro>
{
    new("Dom Casmurro", "Romance", 39.90m, 12),
    new("O Cortiço", "Romance", 29.90m, 0),
    new("Sapiens", "História", 69.90m, 5),
    new("Torto Arado", "Romance", 54.90m, 8),
    new("1808", "História", 49.90m, 3),
}.AsQueryable();

string[] buscas = ["Genero=Romance;Estoque>0", "Preco<50;Estoque>0",
    "Genero=História;Preco>60"];
foreach (var busca in buscas)
{
    var filtro = Montar<Livro>(busca);
    var achados = livros.Where(filtro).Select(l => l.Titulo);
    Console.WriteLine(busca);
    Console.WriteLine($"  árvore: {filtro}");
    Console.WriteLine($"  sql:    {Sql(filtro)}");
    Console.WriteLine($"  livros: {string.Join(", ", achados)}");
}

static Expression<Func<T, bool>> Montar<T>(string busca)
{
    var x = Expression.Parameter(typeof(T), "x");
    Expression? corpo = null;
    foreach (var regra in busca.Split(';'))
    {
        var op = regra.First(c => c is '=' or '<' or '>');
        var partes = regra.Split(op);
        var campo = Expression.Property(x, partes[0]);
        var valor = Expression.Constant(Convert.ChangeType(partes[1],
            campo.Type, CultureInfo.InvariantCulture), campo.Type);
        Expression cmp = op switch
        {
            '=' => Expression.Equal(campo, valor),
            '<' => Expression.LessThan(campo, valor),
            _ => Expression.GreaterThan(campo, valor),
        };
        corpo = corpo is null ? cmp : Expression.AndAlso(corpo, cmp);
    }
    return Expression.Lambda<Func<T, bool>>(corpo!, x);
}

static string Sql(Expression e) => e switch
{
    LambdaExpression l => "WHERE " + Sql(l.Body),
    BinaryExpression b =>
        $"{Sql(b.Left)} {Operador(b.NodeType)} {Sql(b.Right)}",
    MemberExpression m => m.Member.Name,
    ConstantExpression { Value: string s } => $"'{s}'",
    ConstantExpression c => FormattableString.Invariant($"{c.Value}"),
    _ => "?",
};

static string Operador(ExpressionType t) => t switch
{
    ExpressionType.AndAlso => "AND", ExpressionType.Equal => "=",
    ExpressionType.LessThan => "<", _ => ">",
};

record Livro(string Titulo, string Genero, decimal Preco,
    int Estoque);

