public class GerenciadorPedido
{
    public string Processar(string cliente, decimal[] itens, bool vip)
    {
        if (itens.Length == 0) return "erro: pedido vazio";
        decimal total = 0;
        foreach (var i in itens) total += i;
        if (vip) total *= 0.9m;
        if (total < 50m) total += 7m;
        return $"{cliente.ToUpper()}|{total:F2}";
    }
}

