public sealed class Precificador
{
    public const decimal TaxaEntrega = 7m;
    public const decimal MinimoSemTaxa = 50m;

    public decimal Total(Pedido p)
    {
        decimal valor = p.Itens.Sum() * (p.Vip ? 0.9m : 1m);
        return valor < MinimoSemTaxa ? valor + TaxaEntrega : valor;
    }
}

