public enum Natureza { Produto, Servico }
public sealed record ItemNota(
    string Nome, int Qtd, decimal Unitario, Natureza Tipo)
{
    public decimal Total => Qtd * Unitario;
}

public interface ICalculoImposto
{
    string Nome { get; }
    decimal Calcular(ItemNota item);
}

public sealed record Aliquota(
    string Nome, Natureza Alvo, decimal Taxa) : ICalculoImposto
{
    public decimal Calcular(ItemNota i) =>
        i.Tipo == Alvo ? i.Total * Taxa : 0m;
}

public sealed class LayoutNota
{
    public IEnumerable<string> Linhas(int numero, string cliente,
        List<ItemNota> itens, Dictionary<string, decimal> impostos)
    {
        yield return $"NF {numero} | {cliente}";
        foreach (var i in itens)
            yield return Coluna($"{i.Qtd}x {i.Nome}", i.Total);
        yield return Coluna("TOTAL", itens.Sum(i => i.Total));
        foreach (var (nome, v) in impostos.Where(x => x.Value > 0))
            yield return Coluna($"tributos {nome}", v);
    }
    private static string Coluna(string rotulo, decimal valor) =>
        $"  {rotulo,-18}{valor,12:N2}";
}

public sealed class EmissorNota(IEnumerable<ICalculoImposto> regras,
    LayoutNota layout, int primeiroNumero)
{
    private int _numero = primeiroNumero;
    public string Emitir(string cliente, List<ItemNota> itens)
    {
        var impostos = regras.ToDictionary(
            r => r.Nome, r => itens.Sum(r.Calcular));
        return string.Join("\n",
            layout.Linhas(_numero++, cliente, itens, impostos));
    }
}

