public sealed record Pacote(string Nome, decimal Peso, string Cep);
public sealed record Cotacao(string Servico, decimal Valor, int Dias)
{
    public string Prazo => Dias == 0 ? "hoje" : $"{Dias} dia(s)";
    public override string ToString() =>
        $"{Servico,-9} R$ {Valor,6:N2}  {Prazo}";
}

public interface IFrete
{
    bool Atende(Pacote p);
    Cotacao Cotar(Pacote p);
}

public sealed record Correios(
    string Servico, decimal Base, decimal PorKg, int Dias) : IFrete
{
    public bool Atende(Pacote p) => p.Peso <= 30m;
    public Cotacao Cotar(Pacote p) =>
        new(Servico, Base + p.Peso * PorKg, Dias);
}

public sealed class Motoboy : IFrete
{
    public bool Atende(Pacote p) =>
        p.Cep.StartsWith("50") && p.Peso <= 5m;
    public Cotacao Cotar(Pacote p) => new("Motoboy", 15m, 0);
}

public sealed class Retirada : IFrete
{
    public bool Atende(Pacote p) => true;
    public Cotacao Cotar(Pacote p) => new("Retirada", 0m, 1);
}

public sealed class CalculadoraFrete(IEnumerable<IFrete> fretes)
{
    public IEnumerable<Cotacao> Cotar(Pacote p) => fretes
        .Where(f => f.Atende(p))
        .Select(f => f.Cotar(p))
