public sealed record Item(string Nome, decimal Preco, int Qtd);
public sealed record Desconto(string Regra, decimal Valor);

public sealed record Carrinho(string Cliente, List<Item> Itens,
    string? Cupom = null, bool Novo = false)
{
    public decimal Subtotal => Itens.Sum(i => i.Preco * i.Qtd);
}

public interface IRegra
{
    Desconto Calcular(Carrinho c);
}

public sealed class Cupom(string codigo, int pct) : IRegra
{
    public Desconto Calcular(Carrinho c) => new($"cupom {codigo}",
        c.Cupom == codigo ? c.Subtotal * pct / 100m : 0m);
}

public sealed class LeveTres(string item) : IRegra
{
    public Desconto Calcular(Carrinho c) => new("leve 3 pague 2",
        c.Itens.Sum(i => i.Nome == item ? i.Qtd / 3 * i.Preco : 0m));
}

public sealed class PrimeiraCompra(int pct) : IRegra
{
    public Desconto Calcular(Carrinho c) => new("primeira compra",
        c.Novo ? c.Subtotal * pct / 100m : 0m);
}

public sealed class Soma(params IRegra[] regras) : IRegra
{
    public Desconto Calcular(Carrinho c)
    {
        var validos = regras.Select(r => r.Calcular(c))
            .Where(d => d.Valor > 0).ToList();
        var nome = string.Join(" + ", validos.Select(d => d.Regra));
        return new(nome == "" ? "sem desconto" : nome,
            validos.Sum(d => d.Valor));
    }
}

public sealed class Melhor(params IRegra[] regras) : IRegra
{
    public Desconto Calcular(Carrinho c) =>
        regras.Select(r => r.Calcular(c)).MaxBy(d => d.Valor)!;
}

