public sealed class Registro<T>
{
    private readonly Dictionary<string, Func<T>> _criadores =
        new(StringComparer.OrdinalIgnoreCase);
    public IEnumerable<string> Nomes => _criadores.Keys.Order();
    public void Registrar(string nome, Func<T> criar) =>
        _criadores[nome] = criar;
