public interface IFrete
{
    Cotacao Calcular(string cepDestino, decimal pesoKg);
}

public sealed class TransportadoraSdk
{
    public int Chamadas { get; private set; }
    public string Cotar(string origem, string destino, int gramas)
    {
        Chamadas++;
        int centavos = 1500 + gramas / 100 * 35;
        int dias = destino.StartsWith('0') ? 2 : 6;
        return $"{centavos};{dias}";
    }
}

public sealed class FreteTransportadora(
    TransportadoraSdk sdk, string cepLoja) : IFrete
{
    public Cotacao Calcular(string cepDestino, decimal pesoKg)
    {
        int gramas = (int)Math.Ceiling(pesoKg * 1000);
        var partes = sdk.Cotar(cepLoja, cepDestino, gramas)
            .Split(';');
        return new Cotacao(
            int.Parse(partes[0]) / 100m, int.Parse(partes[1]));
    }
}

string Resumo(IFrete f, string cep, decimal kg)
{
    var c = f.Calcular(cep, kg);
    return $"CEP {cep}: {c.Valor:C} ({c.Dias} dias)";
}

public sealed class FreteFixo(decimal valor) : IFrete
{
    public Cotacao Calcular(string cepDestino, decimal pesoKg) =>
        new(valor, 3);
}

