public sealed record Leitura(double Celsius, DateTime Quando);

public interface IEstacao
{
    Leitura Ler();
}

public sealed class SensorImportado
{
    public double TempF => 98.6;
    public long UnixSegundos => 1790000000;
}

public sealed class EstacaoAdapter(SensorImportado sensor)
    : IEstacao
{
    public Leitura Ler()
    {
        var quando = DateTimeOffset
            .FromUnixTimeSeconds(sensor.UnixSegundos).UtcDateTime;
        double c = (sensor.TempF - 32) * 5 / 9;
        return new Leitura(Math.Round(c, 1), quando);
    }
}

