public interface IRenderizador
{
    string Circulo(int raio);
    string Retangulo(int largura, int altura);
}

public sealed class RenderTexto : IRenderizador
{
    public string Circulo(int raio) => $"circulo raio {raio}";
    public string Retangulo(int l, int a) => $"retangulo {l}x{a}";
}

public sealed class RenderSvg : IRenderizador
{
    public string Circulo(int raio) => $"<circle r=\"{raio}\"/>";
    public string Retangulo(int l, int a) =>
        $"<rect width=\"{l}\" height=\"{a}\"/>";
}

public abstract class Forma(IRenderizador render)
{
    protected IRenderizador Render { get; } = render;
    public abstract string Desenhar();
    public abstract double Area();
}

public sealed class Circulo(IRenderizador r, int raio) : Forma(r)
{
    public override string Desenhar() => Render.Circulo(raio);
    public override double Area() => Math.PI * raio * raio;
}

public sealed class Quadrado(IRenderizador r, int lado) : Forma(r)
{
    public override string Desenhar() =>
        Render.Retangulo(lado, lado);
    public override double Area() => lado * lado;
}

public sealed class RenderAscii : IRenderizador
{
    public string Circulo(int raio) =>
        "(" + new string('o', raio * 2) + ")";
    public string Retangulo(int l, int a) =>
        $"[{new string('#', l)}] x{a}";
}

IRenderizador[] renders =
    [new RenderTexto(), new RenderSvg(), new RenderAscii()];
foreach (var r in renders)
{
    Forma[] cena = [new Circulo(r, 2), new Quadrado(r, 3)];
    var partes = cena.Select(f => f.Desenhar());
    Console.WriteLine(string.Join(" | ", partes));
}

