public interface IItem
{
    string Nome { get; }
    double Peso { get; }
}

public sealed partial class Bolsa(string nome, double couroKg)
    : IItem
{
    public const int NiveisMax = 3;
    private readonly List<IItem> _dentro = [];
    public string Nome => nome;
    public Bolsa? Pai { get; private set; }
    public IReadOnlyList<IItem> Dentro => _dentro;
    public double Peso => couroKg + _dentro.Sum(i => i.Peso);
}

public sealed partial class Bolsa
{
    public int Nivel => Pai is null ? 1 : Pai.Nivel + 1;
    private Bolsa Raiz => Pai?.Raiz ?? this;
    public int Altura() => 1 + _dentro.OfType<Bolsa>()
        .Select(b => b.Altura()).DefaultIfEmpty(0).Max();
    private string? Problema(Bolsa b) =>
        b.Pai is not null ? "já está em outra bolsa"
        : b == Raiz ? "criaria um ciclo"
        : Nivel + b.Altura() > NiveisMax ? "fundo demais"
        : null;
}

public class InventarioException(string m) : Exception(m);

public sealed partial class Bolsa
{
    public void Guardar(IItem item)
    {
        if (item is Bolsa b && Problema(b) is { } motivo)
            throw new InventarioException($"{b.Nome}: {motivo}");
        if (item is Bolsa nova) nova.Pai = this;
        _dentro.Add(item);
    }
}

string? Caminho(Bolsa bolsa, string alvo)
{
    foreach (var item in bolsa.Dentro)
    {
        if (item.Nome == alvo) return $"{bolsa.Nome} > {alvo}";
        if (item is Bolsa b && Caminho(b, alvo) is { } resto)
            return $"{bolsa.Nome} > {resto}";
    }
    return null;
}
