public interface IArma
{
    string Nome { get; }
    int Dano();
}

public sealed class Espada : IArma
{
    public string Nome => "Espada";
    public int Dano() => 10;
}

public abstract class Encantamento(IArma interna) : IArma
{
    protected IArma Interna { get; } = interna;
    public virtual string Nome => Interna.Nome;
    public virtual int Dano() => Interna.Dano();
}

public sealed class Dobro(IArma a) : Encantamento(a)
{
    public override string Nome => $"{Interna.Nome} dupla";
    public override int Dano() => Interna.Dano() * 2;
