    public override string Nome => $"{Interna.Nome} flamejante";
    public override int Dano() => Interna.Dano() + 5;
}

public sealed class ComLog(IArma a, List<string> log)
    : Encantamento(a)
{
    private int _golpes;
    public override int Dano()
    {
        int d = Interna.Dano();
        log.Add($"golpe {++_golpes}: {Nome} causou {d}");
        return d;
    }
}

