sealed class Barramento
{
    private readonly Dictionary<Type, List<Action<object>>> _mapa =
        [];

    public void Assinar<T>(Action<T> acao)
    {
        if (!_mapa.TryGetValue(typeof(T), out var lista))
        {
            _mapa[typeof(T)] = lista = [];
        }
        lista.Add(m => acao((T)m));
    }

    public void Publicar<T>(T mensagem) where T : notnull
    {
        foreach (var a in _mapa.GetValueOrDefault(typeof(T), []))
        {
            a(mensagem);
        }
    }
}

