public interface IAcao
{
    string Descricao { get; }
    void Executar();
    void Desfazer();
}

public sealed class Planilha
{
    private readonly Dictionary<string, decimal> _celulas = [];
    public decimal? Ler(string c) =>
        _celulas.TryGetValue(c, out var v) ? v : null;
    public void Definir(string c, decimal? v)
    {
        if (v is decimal x) _celulas[c] = x;
        else _celulas.Remove(c);
    }
    public decimal Soma => _celulas.Values.Sum();
}

public sealed class DefinirValor(Planilha p, string cel, decimal v)
    : IAcao
{
    private decimal? _antes;
    public string Descricao => $"{cel} = {v}";
    public void Executar()
    {
        _antes = p.Ler(cel);
        p.Definir(cel, v);
    }
    public void Desfazer() => p.Definir(cel, _antes);
}

public sealed partial class Historico
{
    private readonly Stack<IAcao> _desfazer = new();
    private readonly Stack<IAcao> _refazer = new();

    public void Executar(IAcao acao)
    {
        acao.Executar();
        _desfazer.Push(acao);
        _refazer.Clear();
    }
}

public sealed partial class Historico
{
    public bool Desfazer()
    {
        if (!_desfazer.TryPop(out var acao)) return false;
        acao.Desfazer();
        _refazer.Push(acao);
        return true;
    }
}

public sealed partial class Historico
{
    public bool Refazer()
    {
        if (!_refazer.TryPop(out var acao)) return false;
        acao.Executar();
        _desfazer.Push(acao);
        return true;
    }
}

