// Antes: um método que conhece todas as defesas, na ordem certa
int DanoFinal(int golpe, ref int escudo, int armaduraPct)
{
    int absorvido = Math.Min(escudo, golpe);
    escudo -= absorvido;
    golpe -= absorvido;
    return golpe - golpe * armaduraPct / 100;
}

