public sealed class Golpe(int dano)
{
    public int Dano { get; set; } = dano;
}

public abstract class Defesa
{
    private Defesa? _proxima;
    public Defesa Entao(Defesa proxima) => _proxima = proxima;
    public void Receber(Golpe g)
    {
        Tratar(g);
        if (g.Dano > 0) _proxima?.Receber(g);
    }
    protected abstract void Tratar(Golpe g);
}

public sealed class Escudo(int carga) : Defesa
{
    protected override void Tratar(Golpe g)
    {
        int absorvido = Math.Min(carga, g.Dano);
        carga -= absorvido;
        g.Dano -= absorvido;
        Console.WriteLine($"  escudo absorveu {absorvido}");
    }
}

public sealed class Armadura(int reducaoPct) : Defesa
{
    protected override void Tratar(Golpe g)
    {
        g.Dano -= g.Dano * reducaoPct / 100;
        Console.WriteLine($"  armadura deixou passar {g.Dano}");
    }
}

public sealed class Vida(int pontos) : Defesa
{
    protected override void Tratar(Golpe g)
    {
        pontos -= g.Dano;
        Console.WriteLine($"  vida caiu para {pontos}");
    }
}

