static Status Proximo(Status s, string evento) => (s, evento) switch
{
    (Status.Aberto, "confirmar") => Status.Preparando,
    (Status.Preparando, "despachar") => Status.NaRua,
    (Status.NaRua, "entregar") => Status.Entregue,
    (Status.Aberto or Status.Preparando, "cancelar") =>
        Status.Cancelado,
    _ => throw new InvalidOperationException($"{evento} em {s}?")
};

