class MatriculaDados
{
    public string Aluno { get; set; } = "";
    public string Situacao { get; set; } = "";
    public int Meses { get; set; }
}

static class TrancamentoService
{
    public static void Trancar(MatriculaDados m, int meses)
    {
        if (m.Situacao == "ativa" && meses <= 6)
        {
            m.Situacao = "trancada";
            m.Meses = meses;
        }
    }
}

// Depois: a regra mora com os dados, com os nomes do negócio
