sealed class Matricula(string aluno)
{
    public string Aluno { get; } = aluno;
    public bool Trancada { get; private set; }
    public int Meses { get; private set; }

    public void Trancar(int meses)
    {
        if (Trancada || meses is < 1 or > 6)
            throw new InvalidOperationException("Trancamento inválido");
        (Trancada, Meses) = (true, meses);
    }

    public override string ToString() => Trancada
        ? $"{Aluno}: trancada por {Meses} meses"
        : $"{Aluno}: ativa";
}

