abstract class EntidadeBase<TId> where TId : notnull
{
    public TId Id { get; protected init; } = default!;

    public override bool Equals(object? obj) =>
        obj is EntidadeBase<TId> o && o.GetType() == GetType()
        && EqualityComparer<TId>.Default.Equals(o.Id, Id);

    public override int GetHashCode() => HashCode.Combine(GetType(), Id);

    public static bool operator ==(EntidadeBase<TId>? x,
        EntidadeBase<TId>? y) => x?.Equals(y) ?? y is null;

    public static bool operator !=(EntidadeBase<TId>? x,
        EntidadeBase<TId>? y) => !(x == y);
}

sealed class Jogador : EntidadeBase<int>
{
