sealed record Periodo
{
    public DateOnly Inicio { get; }
    public DateOnly Fim { get; }

    public Periodo(DateOnly inicio, DateOnly fim)
    {
        if (fim < inicio)
            throw new ArgumentException("Fim antes do início");
        (Inicio, Fim) = (inicio, fim);
    }

    public int Dias => Fim.DayNumber - Inicio.DayNumber + 1;
    public bool Contem(DateOnly d) => d >= Inicio && d <= Fim;
}

