public sealed class BaseLivraria
{
    public Dictionary<string, Livro> Livros { get; } = [];
}

public sealed class Senha
{
    private int _atual;
    public int Chamar() => ++_atual;
}

public sealed class ComandosLivraria(BaseLivraria db)
{
    public void Cadastrar(string isbn, string titulo) =>
        db.Livros[isbn] = new Livro(isbn, titulo, 0);

    public void Repor(string isbn, int qtd)
    {
        var l = db.Livros[isbn];
        db.Livros[isbn] = l with { Estoque = l.Estoque + qtd };
    }
}

public sealed class ConsultasLivraria(BaseLivraria db)
{
    public int Estoque(string isbn) => db.Livros[isbn].Estoque;

    public IReadOnlyList<LivroVitrine> Vitrine() =>
        db.Livros.Values
            .OrderBy(l => l.Titulo)
            .Select(l => new LivroVitrine(l.Titulo,
                l.Estoque > 0 ? $"{l.Estoque} em estoque"
                              : "esgotado"))
            .ToList();
}

var db = new BaseLivraria();
var comandos = new ComandosLivraria(db);
var consultas = new ConsultasLivraria(db);
comandos.Cadastrar("978-01", "Vidas Secas");
comandos.Cadastrar("978-02", "Capitães da Areia");

foreach (var item in consultas.Vitrine())
{
    Console.WriteLine($"{item.Titulo}: {item.Situacao}");
}
